/* MathQuest — Mathématiques 5e : chapitres reconstruits (cours propre à chaque notion + générateurs paramétriques), année 2026-2027.
   Programme appliqué : NOUVEAU programme de mathématiques du cycle 4, fixé par l’arrêté du 18 février 2026 (JO du 4 mars 2026,
   NOR MENE2602912A), annexe 2 publiée au BO n°10 du 5 mars 2026 ; il entre en application en classe de 5e à la rentrée 2026
   (4e en 2027, 3e en 2028). Chaque chapitre suit les objectifs d’apprentissage et automatismes de 5e de ce programme.
   Identifiants des chapitres existants conservés (progression des élèves préservée). */
(function(){
'use strict';
const MQ=window.MQCollege;if(!MQ)return;const H=MQ.H;
const {R,P,ch,num,frac,order,bank,pairs,sort,mix,pickN,shuffle,nf,dec,gcd}=H;
const C=(d,u,ex,m,a,r)=>({d,u,ex,m,a,r});const T=(t,h)=>({t,h});
const REF='Mathématiques cycle 4 — arrêté du 18 février 2026 (NOR MENE2602912A), BO n°10 du 5 mars 2026, applicable en 5e à la rentrée 2026';
const PRG='Programme de mathématiques du cycle 4 (2026)';
const pw=(b,e)=>`${b}<sup>${e<0?'−'+(-e):e}</sup>`;
const mono=(a,v)=>a===0?'':a===1?v:a===-1?'−'+v:nf(a)+v;
function poly(...terms){let s='';for(const [c,v] of terms){if(!c)continue;const abs=Math.abs(c);const body=v?(abs===1?v:nf(abs)+v):nf(abs);if(!s)s=(c<0?'−':'')+body;else s+=(c<0?' − ':' + ')+body;}return s||'0';}
const lin=(a,b,v='x')=>poly([a,v],[b,'']);
const par=n=>n<0?`(${nf(n)})`:nf(n);
const fr=(n,d)=>{const g=gcd(n,d)||1;n/=g;d/=g;if(d<0){n=-n;d=-d;}return d===1?nf(n):`${n<0?'−':''}${Math.abs(n)}/${d}`;};
const fracR=(q,n,d,o={})=>{const g=gcd(n,d)||1;let a=n/g,b=d/g;if(b<0){a=-a;b=-b;}return b===1?num(q,a,o):frac(q,a,b,o);};
const irr=(dens,maxN)=>{const d=P(dens);let n=R(1,maxN);let k=0;while((gcd(n,d)!==1||n%d===0)&&k++<40)n=R(1,maxN);if(gcd(n,d)!==1)n=1;return [n,d];};
const eqF=(n,d)=>F(n,d)===fr(n,d)?'':` = ${fr(n,d)}`;
const F=(n,d)=>`${n<0?'−':''}${Math.abs(n)}/${d}`;
const deg=x=>x*Math.PI/180;
/* Repère et droites (x et y de −5 à 5), pour lire des images ou des coefficients. */
function graph(lines){const u=20,o=120,X=x=>o+x*u,Y=y=>o-y*u;let g='';for(let i=-5;i<=5;i++){g+=`<line x1="${X(i)}" y1="${Y(-5.5)}" x2="${X(i)}" y2="${Y(5.5)}" stroke="currentColor" stroke-opacity="0.15"/><line x1="${X(-5.5)}" y1="${Y(i)}" x2="${X(5.5)}" y2="${Y(i)}" stroke="currentColor" stroke-opacity="0.15"/>`;}
  g+=`<line x1="${X(-5.5)}" y1="${Y(0)}" x2="${X(5.5)}" y2="${Y(0)}" stroke="currentColor" stroke-width="1.5"/><line x1="${X(0)}" y1="${Y(-5.5)}" x2="${X(0)}" y2="${Y(5.5)}" stroke="currentColor" stroke-width="1.5"/>`;
  for(const i of [-4,-2,2,4]){g+=`<text x="${X(i)}" y="${Y(0)+14}" font-size="10" text-anchor="middle" fill="currentColor">${i<0?'−'+(-i):i}</text><text x="${X(0)-8}" y="${Y(i)+4}" font-size="10" text-anchor="end" fill="currentColor">${i<0?'−'+(-i):i}</text>`;}
  g+=`<text x="${X(0)-6}" y="${Y(0)+14}" font-size="10" text-anchor="end" fill="currentColor">0</text><text x="${X(1)}" y="${Y(0)+14}" font-size="10" text-anchor="middle" fill="currentColor">1</text><text x="${X(0)-8}" y="${Y(1)+4}" font-size="10" text-anchor="end" fill="currentColor">1</text>`;
  for(const [a,b] of lines){const x1=-6,x2=6;g+=`<line x1="${X(x1)}" y1="${Y(a*x1+b)}" x2="${X(x2)}" y2="${Y(a*x2+b)}" stroke="#2563eb" stroke-width="2.5"/>`;}
  return `<svg class="fig pfig" viewBox="0 0 240 240" width="240" height="240" role="img" aria-label="Repère avec une droite" style="overflow:hidden">${g}</svg>`;}
const multiP=(q,x,y)=>({type:'multi',q,labels:['abscisse','ordonnée'],ans:[x,y],expl:`Le point a pour coordonnées <b>(${nf(x)} ; ${nf(y)})</b> : abscisse ${nf(x)}, ordonnée ${nf(y)}.`,hint:'Abscisse sur l’axe horizontal, ordonnée sur l’axe vertical.'});

MQ.add('maths','5',[
/* ======================= 5a ======================= */
{id:'5a',name:'Enchaînements d’opérations, priorités et divisibilité',icon:'🧮',domain:'Nombres et calculs',
 refs:[REF,PRG+' — Nombres et calculs, 5e, « Opérations » : enchaîner des opérations, priorités opératoires, distributivité simple sur des exemples numériques, multiples et diviseurs, critères de divisibilité par 3 et par 9'],
 tip:'Dans un calcul sans parenthèses, la multiplication et la division passent avant l’addition et la soustraction ; ensuite on calcule de gauche à droite.',
 c:C(`Calcule 3 + 4 × 5 : est-ce 35 ou 23 ? Tout le monde doit trouver le même résultat ; c’est pourquoi on a fixé des <b>règles de priorité</b>. Elles permettent aussi de traduire un programme de calcul en une seule expression.`,
  [T('Priorités opératoires',`<p>1. On calcule d’abord ce qui est entre <b>parenthèses</b>.</p><p>2. Puis les <b>multiplications et divisions</b>, de gauche à droite.</p><p>3. Enfin les <b>additions et soustractions</b>, de gauche à droite.</p><p>3 + 4 × 5 = 3 + 20 = <b>23</b> ; (3 + 4) × 5 = 7 × 5 = <b>35</b> ; 20 − 8 ÷ 2 = 20 − 4 = 16.</p><p>Un calcul se nomme d’après sa <b>dernière opération</b> : 3 + 4 × 5 est une <b>somme</b> (de termes) ; (3 + 4) × 5 est un <b>produit</b> (de facteurs).</p>`),
   T('Distributivité et divisibilité',`<p>Distributivité simple : k × (a + b) = k × a + k × b. Calcul astucieux : 7 × 102 = 7 × 100 + 7 × 2 = 714.</p><p>a est un <b>multiple</b> de b (et b un <b>diviseur</b> de a) si la division de a par b tombe juste : 35 = 5 × 7.</p><p>Critères : divisible par 2 si le chiffre des unités est pair ; par 5 s’il se termine par 0 ou 5 ; par 10 s’il se termine par 0 ; par <b>3</b> si la somme de ses chiffres est un multiple de 3 ; par <b>9</b> si la somme de ses chiffres est un multiple de 9 (522 : 5 + 2 + 2 = 9 → divisible par 9).</p>`)],
  [{q:'Calculer A = 18 − 3 × (2 + 4) ÷ 9.',s:['Parenthèses : 2 + 4 = 6.','Multiplication et division de gauche à droite : 3 × 6 = 18 ; 18 ÷ 9 = 2.','Soustraction : 18 − 2 = 16.']}],
  ['Je calcule les parenthèses (les plus intérieures d’abord).','Je fais les multiplications et divisions de gauche à droite.','Je termine par les additions et soustractions de gauche à droite.','Je souligne à chaque étape le calcul effectué.'],
  ['Calculer de gauche à droite sans respecter les priorités : 3 + 4 × 5 ≠ 35.','Oublier une parenthèse en traduisant un programme de calcul.','Croire qu’un nombre est divisible par 3 parce qu’il se termine par 3.'],
  ['Parenthèses, puis × et ÷, puis + et −.','Somme ou produit : on regarde la dernière opération effectuée.','Divisible par 3 (ou 9) : somme des chiffres multiple de 3 (ou 9).']),
 g:mix([d=>{const a=R(2,20),b=R(2,9),c=R(2,9);const t=P(['a+b*c','a*b+c','a-b*c','(a+b)*c','a*(b+c)']);let v,s;
   if(t==='a+b*c'){v=a+b*c;s=`${a} + ${b} × ${c}`;}else if(t==='a*b+c'){v=a*b+c;s=`${a} × ${b} + ${c}`;}else if(t==='a-b*c'){const A=a+b*c;v=A-b*c+0;s=`${A+0} − ${b} × ${c}`;v=a;}else if(t==='(a+b)*c'){v=(a+b)*c;s=`(${a} + ${b}) × ${c}`;}else{v=a*(b+c);s=`${a} × (${b} + ${c})`;}
   return num(`Calcule : <b>${s}</b>`,v,{expl:`On respecte les priorités (parenthèses, puis ×, puis + et −) : <b>${nf(v)}</b>.`,hint:'La multiplication passe avant l’addition.'});},3],
  [d=>{const a=R(2,9),b=R(2,9),c=R(2,6),e=b*c*R(1,4);return num(`Calcule : <b>${a} + ${e} ÷ ${b} × ${c}</b>`,a+e/b*c,{expl:`÷ et × de gauche à droite : ${e} ÷ ${b} = ${e/b} ; ${e/b} × ${c} = ${e/b*c} ; puis ${a} + ${e/b*c} = <b>${a+e/b*c}</b>.`,hint:'Divisions et multiplications de gauche à droite.'});},2],
  [d=>{const n=d===1?R(100,999):R(1000,99999);const k=P([3,9]);const s=String(n).split('').reduce((x,y)=>x+ +y,0);const ok=s%k===0;return ch(`Le nombre <b>${nf(n)}</b> est-il divisible par ${k} ?`,ok?'Oui':'Non',[ok?'Non':'Oui'],{expl:`Somme des chiffres : ${String(n).split('').join(' + ')} = ${s}, ${ok?'':'qui n’est pas '}un multiple de ${k}${ok?'':''} : ${ok?'divisible':'pas divisible'} par ${k}.`,hint:`Additionne les chiffres et regarde si la somme est dans la table de ${k}.`});},3],
  [d=>{const t=P([[[3,'(2 + 5)'],'3 × (2 + 5)',21],[[4,'(10 − 3)'],'4 × (10 − 3)',28]]);const k=R(3,9),a=P([100,10,1000]),b=R(1,9);return num(`Calcule astucieusement : ${k} × ${a+b} (pense à ${k} × ${a} + ${k} × ${b}).`,k*(a+b),{expl:`${k} × (${a} + ${b}) = ${k*a} + ${k*b} = <b>${nf(k*(a+b))}</b>.`,hint:'Distributivité : k × (a + b) = k × a + k × b.'});},1],
  [d=>{const opt=[['3 + 4 × 5','une somme'],['(3 + 4) × 5','un produit'],['8 × 2 − 3','une différence'],['8 × (2 − 3)','un produit'],['(9 − 1) ÷ 2','un quotient'],['9 − 1 ÷ 2','une différence']];const [e,good]=P(opt);return ch(`L’expression <b>${e}</b> est…`,good,['une somme','un produit','une différence','un quotient'].filter(x=>x!==good),{expl:`On regarde la dernière opération effectuée selon les priorités : ${e} est <b>${good}</b>.`,hint:'Quelle opération fait-on en dernier ?'});},2],
  [d=>{const q=R(2,15),b=R(3,9),r=R(1,b-1);const a=b*q+r;return ch(`Quelle égalité traduit la division euclidienne de ${a} par ${b} ?`,`${a} = ${b} × ${q} + ${r}`,[`${a} = ${b} × ${q+1} + ${r}`,`${a} = ${b} × ${q} + ${r+b}`,`${a} = ${q} × ${r} + ${b}`],{expl:`${b} × ${q} = ${b*q} et ${a} − ${b*q} = ${r} (&lt; ${b}) : <b>${a} = ${b} × ${q} + ${r}</b>.`,hint:'Le reste doit être plus petit que le diviseur.'});},1])},

/* ======================= 5b ======================= */
{id:'5b',name:'Découvrir les nombres relatifs',icon:'🌡️',domain:'Nombres et calculs',
 refs:[REF,PRG+' — 5e, « Nombres relatifs » : définir les nombres relatifs, l’opposé, la valeur absolue ; lire et placer sur une droite graduée ; comparer et ranger'],
 tip:'Sur une droite graduée, plus un nombre est à droite, plus il est grand : −2 &gt; −7 car −2 est plus à droite.',
 c:C(`Il fait −5 °C à Moscou et 3 °C à Paris ; une plongée atteint −12 m. Pour représenter des grandeurs qui peuvent être en dessous de zéro, on utilise les <b>nombres relatifs</b>.`,
  [T('Définitions',`<p>Un nombre relatif est formé d’un <b>signe</b> (+ ou −) et d’une <b>distance à zéro</b> (sa valeur absolue). −5 est <b>négatif</b>, 3 (ou +3) est <b>positif</b> ; 0 est à la fois positif et négatif.</p><p>Deux nombres <b>opposés</b> ont la même distance à zéro et des signes contraires : 4 et −4. La <b>valeur absolue</b> de −4 est 4.</p>`),
   T('Droite graduée et comparaison',`<p>Sur une droite graduée, chaque point est repéré par son <b>abscisse</b> : les nombres négatifs sont à gauche de 0, les positifs à droite.</p><p>Comparer : un nombre positif est toujours plus grand qu’un négatif ; entre deux négatifs, le plus grand est celui qui a la plus petite distance à zéro : <b>−3 &gt; −8</b>.</p><p>Ordre croissant : −8 &lt; −3 &lt; 0 &lt; 2 &lt; 5.</p>`)],
  [{q:'Ranger dans l’ordre croissant : 4 ; −6 ; −1,5 ; 0 ; −10.',s:['Les négatifs d’abord : celui qui est le plus loin de 0 est le plus petit.','−10 &lt; −6 &lt; −1,5.','Puis 0, puis 4 : −10 &lt; −6 &lt; −1,5 &lt; 0 &lt; 4.']}],
  ['Je repère le signe de chaque nombre.','Je compare d’abord les signes.','Entre deux négatifs, le plus petit est le plus éloigné de zéro.','Je vérifie en imaginant les nombres sur une droite graduée.'],
  ['Croire que −8 &gt; −3 parce que 8 &gt; 3.','Oublier que 0 est plus grand que tout nombre négatif.','Confondre l’opposé (−4 ↔ 4) et l’inverse.'],
  ['Opposés : même distance à zéro, signes contraires.','Plus à droite sur la droite graduée = plus grand.','Entre deux négatifs, le plus grand est le plus proche de zéro.']),
 g:mix([d=>{let a=R(-15,15),b=R(-15,15);if(a===b)b++;const g=Math.max(a,b);return ch(`Quel est le plus grand nombre : <b>${nf(a)}</b> ou <b>${nf(b)}</b> ?`,nf(g),[nf(Math.min(a,b))],{expl:`${nf(g)} est plus à droite sur la droite graduée : ${nf(g)} &gt; ${nf(Math.min(a,b))}.`,hint:'Imagine les deux nombres sur une droite graduée.'});},3],
  [d=>{const v=pickN([-12,-8,-5,-3,-1,0,2,4,7,9,-0.5,-2.5,1.5],5);const s=v.slice().sort((a,b)=>a-b);return order('Range dans l’ordre <b>croissant</b> :',s.map(nf),{expl:s.map(nf).join(' &lt; '),hint:'Commence par le négatif le plus éloigné de zéro.'});},2],
  [d=>{const a=R(1,20)*P([1,-1]);const t=P(['opposé','valeur absolue']);return num(`Quel est ${t==='opposé'?'l’opposé':'la valeur absolue'} de <b>${nf(a)}</b> ?`,t==='opposé'?-a:Math.abs(a),{expl:t==='opposé'?`L’opposé de ${nf(a)} est <b>${nf(-a)}</b> (même distance à 0, signe contraire).`:`La distance de ${nf(a)} à zéro est <b>${Math.abs(a)}</b>.`,hint:t==='opposé'?'Change le signe.':'C’est la distance à zéro.'});},2],
  [d=>{const step=P([1,2,5]),start=-4*step,i=R(0,8);const val=start+i*step;return num(`${H.SVG.line(start,start+8*step,step,val,[start,0,start+8*step])}Quelle est l’abscisse du point marqué par la flèche ?`,val,{expl:`On compte les graduations depuis 0 (pas de ${step}) : l’abscisse est <b>${nf(val)}</b>.`,hint:'Repère le zéro et le pas de la graduation.'});},2],
  [bank([['À −20 m sous le niveau de la mer, l’altitude est…','négative',['positive','nulle','impossible à écrire'],'Sous le niveau de la mer : nombre négatif.'],{tf:'0 est plus grand que −100.',v:true,e:'Tout nombre négatif est plus petit que 0.'},['Quel nombre est le plus petit ?','−7',['−2','0','3'],'−7 est le plus loin de zéro du côté négatif.']]),1])},

/* ======================= 5c ======================= */
{id:'5c',name:'Additionner et soustraire des relatifs',icon:'➕',domain:'Nombres et calculs',
 refs:[REF,PRG+' — 5e, « Nombres relatifs » : additionner, soustraire, enchaîner additions et soustractions de décimaux relatifs ; résoudre des problèmes'],
 tip:'Soustraire un nombre, c’est ajouter son opposé : 3 − (−5) = 3 + 5 = 8.',
 c:C(`Le matin il fait −4 °C ; la température monte de 7 °C. Quelle température l’après-midi ? Pour calculer avec des températures, des altitudes ou des comptes bancaires, on additionne et on soustrait des <b>nombres relatifs</b>.`,
  [T('Addition',`<p><b>Même signe</b> : on additionne les distances à zéro et on garde le signe : (−4) + (−3) = −7.</p><p><b>Signes contraires</b> : on soustrait la plus petite distance à zéro de la plus grande et on prend le signe de celui qui est le plus loin de zéro : (−4) + 7 = 3 ; 2 + (−9) = −7.</p><p>La somme de deux opposés vaut 0 : 5 + (−5) = 0.</p>`),
   T('Soustraction et suites de calculs',`<p><b>Soustraire un nombre, c’est ajouter son opposé</b> : 3 − 8 = 3 + (−8) = −5 ; 3 − (−8) = 3 + 8 = 11.</p><p>Pour une suite d’additions et de soustractions, on transforme les soustractions en additions, puis on regroupe les positifs et les négatifs : 5 − 9 + 3 − (−2) = 5 + (−9) + 3 + 2 = 10 + (−9) = 1.</p>`)],
  [{q:'Un sous-marin est à −120 m. Il remonte de 45 m, puis redescend de 30 m. À quelle profondeur est-il ?',s:['−120 + 45 = −75.','−75 − 30 = −75 + (−30) = −105.','Il est à −105 m (105 m sous la surface).']}],
  ['Je transforme chaque soustraction en addition de l’opposé.','Pour chaque addition : même signe → j’ajoute ; signes contraires → je soustrais les distances.','Je garde le signe du nombre le plus éloigné de zéro.','Je vérifie avec une droite graduée.'],
  ['Calculer (−4) + 7 = −11 en additionnant les distances.','Oublier de changer le signe : 3 − (−8) ≠ −5.','Confondre le signe d’une opération et le signe d’un nombre.'],
  ['Même signe : on additionne les distances.','Signes contraires : on soustrait, signe du plus éloigné de zéro.','a − b = a + (opposé de b).']),
 g:mix([d=>{const a=R(-15,15),b=R(-15,15)||-4;return num(`Calcule : ${nf(a)} + ${par(b)}`,a+b,{expl:`${(a<0)===(b<0)?'Même signe : on additionne les distances':'Signes contraires : on soustrait les distances, signe du plus éloigné de zéro'} → <b>${nf(a+b)}</b>.`,hint:'Regarde les signes.'});},3],
  [d=>{const a=R(-15,15),b=R(-15,15)||3;return num(`Calcule : ${nf(a)} − ${par(b)}`,a-b,{expl:`${nf(a)} − ${par(b)} = ${nf(a)} + ${par(-b)} = <b>${nf(a-b)}</b>.`,hint:'Soustraire = ajouter l’opposé.'});},3],
  [d=>{const t=R(-10,5),u=R(3,15);return num(`Le matin il fait ${nf(t)} °C. La température monte de ${u} °C. Quelle température fait-il ensuite ?`,t+u,{unit:'°C',expl:`${nf(t)} + ${u} = <b>${nf(t+u)} °C</b>.`,hint:'Une hausse : on ajoute.'});},2],
  [d=>{const v=Array.from({length:4},()=>R(-9,9)||2);const ops=['+','−','+'].map(()=>P(['+','−']));let s=nf(v[0]),res=v[0];for(let i=1;i<4;i++){s+=` ${ops[i-1]} ${par(v[i])}`;res+=ops[i-1]==='+'?v[i]:-v[i];}return num(`Calcule : ${s}`,res,{expl:`On transforme les soustractions en additions de l’opposé, puis on regroupe : <b>${nf(res)}</b>.`,hint:'Regroupe positifs et négatifs.'});},2],
  [bank([['Que vaut 5 + (−5) ?','0',['10','−10','−25'],'Deux opposés ont une somme nulle.'],{tf:'−3 − 4 = −7.',v:true,e:'−3 − 4 = −3 + (−4) = −7.'},['Écart entre −8 °C et 5 °C ?','13 °C',['3 °C','−3 °C','−13 °C'],'5 − (−8) = 13.',2]]),1])},

/* ======================= 5d ======================= */
{id:'5d',name:'Nombres rationnels et fractions',icon:'🍕',domain:'Nombres et calculs',
 refs:[REF,PRG+' — 5e, « Nombres rationnels » : fractions égales, comparer des fractions, additionner et soustraire des fractions de dénominateurs quelconques, fraction d’un nombre'],
 tip:'Pour additionner ou comparer deux fractions, mets-les au même dénominateur en multipliant le numérateur et le dénominateur par un même nombre.',
 c:C(`Tu manges 1/4 d’une pizza et ton amie 2/3 de la même pizza. Avez-vous mangé plus d’une pizza ? Pour le savoir, il faut <b>comparer</b> et <b>additionner</b> des fractions de dénominateurs différents.`,
  [T('Fractions égales et comparaison',`<p>On ne change pas une fraction en multipliant (ou divisant) son numérateur et son dénominateur par un même nombre non nul : 2/3 = 4/6 = 10/15.</p><p>Pour <b>comparer</b>, on met au même dénominateur : 2/3 = 8/12 et 3/4 = 9/12, donc 2/3 &lt; 3/4. Une fraction est plus grande que 1 quand son numérateur dépasse son dénominateur : 17/5 = 3 + 2/5.</p>`),
   T('Addition et soustraction',`<p>Avec le même dénominateur : on additionne les numérateurs : 3/7 + 2/7 = 5/7.</p><p>Avec des dénominateurs différents : on cherche un dénominateur commun : 1/4 + 2/3 = 3/12 + 8/12 = <b>11/12</b> &lt; 1.</p><p>Fraction d’un nombre : 3/4 de 20 = 20 ÷ 4 × 3 = 15.</p>`)],
  [{q:'Calculer 5/6 − 1/4.',s:['Dénominateur commun : 12 (multiple de 6 et de 4).','5/6 = 10/12 et 1/4 = 3/12.','10/12 − 3/12 = 7/12.']}],
  ['Je cherche un dénominateur commun (souvent le plus petit multiple commun).','Je transforme chaque fraction.','J’additionne ou je soustrais les numérateurs, je garde le dénominateur.','Je simplifie si possible.'],
  ['Additionner les dénominateurs : 1/4 + 2/3 ≠ 3/7.','Ne multiplier que le dénominateur pour changer de dénominateur.','Croire que 1/5 &gt; 1/3 parce que 5 &gt; 3.'],
  ['a/b = (a × k)/(b × k).','Même dénominateur pour additionner, soustraire, comparer.','Fraction d’un nombre : on divise puis on multiplie.']),
 g:mix([d=>{const [a,b]=irr([2,3,4,5,6],5),[c,dd]=irr([3,4,6,8,10,12].filter(x=>x!==b),7);const s=P(d===1?[1]:[1,-1]);const n=a*dd+s*c*b;if(n<=0)return fracR(`Calcule et simplifie : ${F(a,b)} + ${F(c,dd)}`,a*dd+c*b,b*dd,{expl:`${F(a*dd,b*dd)} + ${F(c*b,b*dd)} = <b>${F(a*dd+c*b,b*dd)}${eqF(a*dd+c*b,b*dd)}</b>.`,hint:'Même dénominateur.'});
   return fracR(`Calcule et simplifie : ${F(a,b)} ${s>0?'+':'−'} ${F(c,dd)}`,n,b*dd,{expl:`Même dénominateur : ${F(a*dd,b*dd)} ${s>0?'+':'−'} ${F(c*b,b*dd)} = <b>${F(n,b*dd)}${eqF(n,b*dd)}</b>.`,hint:'Réduis au même dénominateur.'});},3],
  [d=>{const [a,b]=irr([3,4,5,6,7,8],7),[c,dd]=irr([3,4,5,6,7,9].filter(x=>x!==b),8);const v1=a/b,v2=c/dd;if(v1===v2)return ch(`Compare ${F(a,b)} et ${F(c,dd)}.`,'elles sont égales',['la première est plus grande','la seconde est plus grande'],{expl:'Elles sont égales.'});
   return ch(`Quelle fraction est la plus grande : ${F(a,b)} ou ${F(c,dd)} ?`,v1>v2?F(a,b):F(c,dd),[v1>v2?F(c,dd):F(a,b),'elles sont égales'],{expl:`${F(a,b)} = ${F(a*dd,b*dd)} et ${F(c,dd)} = ${F(c*b,b*dd)} : la plus grande est <b>${v1>v2?F(a,b):F(c,dd)}</b>.`,hint:'Mets-les au même dénominateur.'});},2],
  [d=>{const b0=P([2,3,4,5,6,8,10]);const [a,b]=irr([b0],b0-1);const k=R(2,8);return num(`Calcule ${F(a,b)} de ${b*k}.`,a*k,{expl:`${b*k} ÷ ${b} = ${k} ; ${k} × ${a} = <b>${a*k}</b>.`,hint:'Divise par le dénominateur, puis multiplie par le numérateur.'});},2],
  [d=>{const [a,b]=irr([3,4,5,6,7],6),k=R(2,6);return num(`${F(a,b)} = ?/${b*k} : quel est le numérateur manquant ?`,a*k,{expl:`On a multiplié le dénominateur par ${k} ; on multiplie aussi le numérateur : ${a} × ${k} = <b>${a*k}</b>.`,hint:'Même multiplication en haut et en bas.'});},1],
  [d=>{const b=P([3,4,5,6,7]),q=R(1,4),r=R(1,b-1);const n=q*b+r;return ch(`Écris ${F(n,b)} sous la forme d’un entier plus une fraction inférieure à 1.`,`${q} + ${F(r,b)}`,[`${q+1} + ${F(r,b)}`,`${r} + ${F(q,b)}`,`${q} + ${F(r,n)}`],{expl:`${n} = ${q} × ${b} + ${r} donc ${F(n,b)} = <b>${q} + ${F(r,b)}</b>.`,hint:'Combien de fois le dénominateur dans le numérateur ?'});},1])},

/* ======================= 5e ======================= */
{id:'5e',name:'Carrés, cubes et puissances simples',icon:'🟥',domain:'Nombres et calculs',
 refs:[REF,PRG+' — 5e, « Puissances » : notion de puissance (carré, cube), carrés des entiers de 0 à 12, cube de 10, calculs d’expressions avec des puissances simples'],
 tip:'5² = 5 × 5 = 25 (et pas 5 × 2 = 10) ; 2³ = 2 × 2 × 2 = 8.',
 c:C(`L’aire d’un carré de côté 7 cm vaut 7 × 7 = 49 cm² ; le volume d’un cube d’arête 3 cm vaut 3 × 3 × 3 = 27 cm³. Ces produits d’un nombre par lui-même s’écrivent avec une <b>puissance</b> : 7² et 3³.`,
  [T('Carré et cube',`<p>Le <b>carré</b> d’un nombre a se note a² (« a au carré ») : a² = a × a. Le <b>cube</b> se note a³ : a³ = a × a × a.</p><p>Carrés à connaître : 0, 1, 4, 9, 16, 25, 36, 49, 64, 81, 100, 121, 144 (de 0² à 12²). 10³ = 1 000.</p><p>Le nom vient de la géométrie : aire du carré = côté², volume du cube = arête³.</p>`),
   T('Calculer avec des puissances',`<p>Les puissances sont prioritaires sur les multiplications et les additions : 2 × 3² = 2 × 9 = 18 ; 3 + 4² = 3 + 16 = 19 ; (3 + 4)² = 7² = 49.</p><p>Avec une lettre : pour x = 5, x² + 1 = 25 + 1 = 26 et 2x² = 2 × 25 = 50.</p>`)],
  [{q:'Calculer A = 5 × 2³ − 4².',s:['Les puissances d’abord : 2³ = 8 et 4² = 16.','Puis la multiplication : 5 × 8 = 40.','A = 40 − 16 = 24.']}],
  ['Je calcule d’abord les puissances.','Puis les multiplications et divisions.','Puis les additions et soustractions.','Je vérifie que je n’ai pas multiplié par l’exposant.'],
  ['Calculer 5² = 10 (multiplier par 2 au lieu de multiplier 5 par lui-même).','Calculer 2 × 3² comme (2 × 3)² = 36.','Confondre 10³ (1 000) et 30.'],
  ['a² = a × a ; a³ = a × a × a.','Carrés de 0 à 12 par cœur ; 10³ = 1 000.','Puissances avant × et +.']),
 g:mix([d=>{const a=R(0,12);return num(`Calcule <b>${a}²</b>.`,a*a,{expl:`${a}² = ${a} × ${a} = <b>${a*a}</b>.`,hint:'Multiplie le nombre par lui-même.'});},3],
  [d=>{const a=R(1,d===1?5:10);return num(`Calcule <b>${a}³</b>.`,a**3,{expl:`${a}³ = ${a} × ${a} × ${a} = <b>${nf(a**3)}</b>.`,hint:'Trois facteurs égaux.'});},2],
  [d=>{const a=R(2,5),b=R(2,4),c=R(1,9);const t=P(['a*b2','c+b2','(c+b)2']);if(t==='a*b2')return num(`Calcule : ${a} × ${b}²`,a*b*b,{expl:`${b}² = ${b*b} ; ${a} × ${b*b} = <b>${a*b*b}</b>.`,hint:'La puissance d’abord.'});if(t==='c+b2')return num(`Calcule : ${c} + ${b}³`,c+b**3,{expl:`${b}³ = ${b**3} ; ${c} + ${b**3} = <b>${c+b**3}</b>.`,hint:'La puissance d’abord.'});return num(`Calcule : (${c} + ${b})²`,(c+b)**2,{expl:`Parenthèses : ${c+b} ; puis ${c+b}² = <b>${(c+b)**2}</b>.`,hint:'Parenthèses d’abord.'});},2],
  [d=>{const n=P([4,9,16,25,36,49,64,81,100,121,144,8,27,64,125,1000]);const isC=[8,27,125,1000].includes(n);const r=isC?Math.round(Math.cbrt(n)):Math.round(Math.sqrt(n));return ch(`Écris <b>${nf(n)}</b> sous la forme d’une puissance.`,isC?`${r}³`:`${r}²`,[isC?`${r}²`:`${r}³`,`${n/2}²`,`${n}¹`].filter(x=>!x.startsWith('0.')),{expl:`${isC?`${r} × ${r} × ${r}`:`${r} × ${r}`} = ${nf(n)} donc ${nf(n)} = <b>${isC?r+'³':r+'²'}</b>.`,hint:'Quel nombre multiplié par lui-même donne ce nombre ?'});},1],
  [d=>{const x=R(1,9),t=P(['x2+1','2x2','x3']);const v=t==='x2+1'?x*x+1:t==='2x2'?2*x*x:x**3;const e=t==='x2+1'?'x² + 1':t==='2x2'?'2x²':'x³';return num(`Pour x = ${x}, calcule <b>${e}</b>.`,v,{expl:`On remplace x par ${x} : <b>${v}</b>.`,hint:'Remplace x, puis calcule la puissance d’abord.'});},2])},

/* ======================= 5f ======================= */
{id:'5f',name:'Expressions littérales et substitution',icon:'🔤',domain:'Nombres et calculs',
 refs:[REF,PRG+' — 5e, « Calcul littéral et algébrique » : produire des formules, calculer par substitution, tester une égalité, reconnaître somme ou produit, contre-exemple'],
 tip:'Pour remplacer une lettre, écris le nombre entre parenthèses à la place de la lettre et rétablis les signes × cachés : 3x devient 3 × (valeur).',
 c:C(`Le périmètre d’un carré de côté c s’écrit 4 × c, ou plus simplement <b>4c</b>. Avec une seule formule, on peut calculer le périmètre de tous les carrés : c’est la force du <b>calcul littéral</b>.`,
  [T('Écrire une formule',`<p>Une lettre désigne un nombre qui peut varier. On supprime souvent le signe × devant une lettre ou une parenthèse : 3 × x = 3x ; a × b = ab ; x × x = x².</p><p>Formules : double de n : 2n ; triple : 3n ; successeur : n + 1 ; prédécesseur : n − 1 ; périmètre du rectangle : 2 × (L + l) ; aire du rectangle : L × l.</p>`),
   T('Substituer, tester, contre-exemple',`<p><b>Substituer</b>, c’est remplacer la lettre par un nombre : pour x = 4, 3x + 2 = 3 × 4 + 2 = 14.</p><p><b>Tester une égalité</b> : 2x + 3 = 11 est vraie pour x = 4 (8 + 3 = 11), fausse pour x = 1.</p><p>Un seul <b>contre-exemple</b> suffit pour montrer qu’une affirmation générale est fausse : « n² &gt; n pour tout n » est fausse car 1² = 1.</p>`)],
  [{q:'Calculer 5x − 2y pour x = 3 et y = 4.',s:['On remplace : 5 × 3 − 2 × 4.','Priorités : 15 − 8.','Résultat : 7.']}],
  ['Je remplace chaque lettre par sa valeur.','Je rétablis les signes × cachés.','Je calcule en respectant les priorités.','Je conclus en précisant la valeur de la lettre utilisée.'],
  ['Écrire 3x = 34 pour x = 4 (juxtaposer au lieu de multiplier).','Confondre x² et 2x.','Croire qu’un exemple qui marche prouve une propriété générale.'],
  ['3x = 3 × x ; x² = x × x.','Substituer = remplacer la lettre par un nombre.','Un contre-exemple suffit à prouver qu’une affirmation est fausse.']),
 g:mix([d=>{const a=R(2,9),b=R(1,15),x=R(1,d===1?10:15);return num(`Calcule ${a}x + ${b} pour x = ${x}.`,a*x+b,{expl:`${a} × ${x} + ${b} = ${a*x} + ${b} = <b>${a*x+b}</b>.`,hint:'3x veut dire 3 × x.'});},3],
  [d=>{const a=R(2,6),b=R(2,6),x=R(1,9),y=R(1,9);return num(`Calcule ${a}x − ${b}y pour x = ${x} et y = ${y}.`,a*x-b*y,{expl:`${a} × ${x} − ${b} × ${y} = ${a*x} − ${b*y} = <b>${nf(a*x-b*y)}</b>.`,hint:'Remplace chaque lettre par sa valeur.'});},2],
  [d=>{const f=P([['le double de n','2n',['n + 2','n²','2 + 2n']],['le triple de n augmenté de 5','3n + 5',['3(n + 5)','n + 15','5n + 3']],['le successeur de n','n + 1',['n − 1','2n','1n']],['le carré de n','n²',['2n','n + n','n × 2']],['le périmètre d’un carré de côté n','4n',['n⁴','n²','n + 4']],['l’aire d’un rectangle de côtés n et 3','3n',['n + 3','2n + 6','n³']]]);return ch(`Quelle expression traduit <b>${f[0]}</b> ?`,f[1],f[2],{expl:`${f[0].charAt(0).toUpperCase()+f[0].slice(1)} s’écrit <b>${f[1]}</b>.`,hint:'Traduis mot à mot.'});},2],
  [d=>{const a=R(2,5),b=R(1,9),x0=R(1,6),c=a*x0+b;const x=P([x0,x0+1,x0-1>0?x0-1:x0+2]);return ch(`L’égalité ${a}x + ${b} = ${c} est-elle vraie pour x = ${x} ?`,x===x0?'Oui':'Non',[x===x0?'Non':'Oui'],{expl:`Pour x = ${x} : ${a} × ${x} + ${b} = ${a*x+b}, ${a*x+b===c?'égal':'différent de'} ${c}.`,hint:'Remplace et calcule.'});},2],
  [bank([['Pour prouver que « pour tout nombre n, n² est plus grand que n » est faux, il suffit…','de donner un contre-exemple (n = 1)',['de calculer 5²','de tester n = 10','d’écrire n² &gt; n'],'1² = 1 n’est pas plus grand que 1.'],['L’expression 3x + 2 est…','une somme',['un produit','un quotient','une différence'],'La dernière opération est l’addition.'],['L’expression 3(x + 2) est…','un produit',['une somme','une différence','un carré'],'La dernière opération est la multiplication.']]),1])},

/* ======================= 5g ======================= */
{id:'5g',name:'Distributivité : développer et factoriser',icon:'🧩',domain:'Nombres et calculs',
 refs:[REF,PRG+' — 5e, « Calcul littéral et algébrique » : exploiter k(a + b) = ka + kb et k(a − b) = ka − kb pour développer ou factoriser ; réduire ax + b'],
 tip:'Développer : la flèche part du facteur et touche chaque terme de la parenthèse. Factoriser : cherche ce qui se répète dans chaque terme.',
 c:C(`Un jardin rectangulaire mesure 5 m de large et (x + 3) m de long. Son aire s’écrit 5(x + 3), ou bien 5x + 15. Passer de l’une à l’autre écriture, c’est utiliser la <b>distributivité</b>.`,
  [T('Développer et factoriser',`<p><b>k(a + b) = ka + kb</b> et <b>k(a − b) = ka − kb</b>.</p><p>Développer (produit → somme) : 4(x + 2) = 4x + 8 ; 3(2x − 5) = 6x − 15.</p><p>Factoriser (somme → produit) : 7x + 21 = 7 × x + 7 × 3 = 7(x + 3).</p>`),
   T('Réduire',`<p>On regroupe les termes en x entre eux et les nombres entre eux : 3x + 5 + 2x − 1 = <b>5x + 4</b>.</p><p>Attention : 3x + 5 ne se réduit pas en 8x. Seuls des termes « de même nature » s’additionnent.</p><p>Démontrer par le calcul littéral : la somme de trois entiers consécutifs n + (n + 1) + (n + 2) = 3n + 3 = 3(n + 1) est toujours un multiple de 3.</p>`)],
  [{q:'Développer et réduire 2(3x + 4) + 5x.',s:['2(3x + 4) = 6x + 8.','6x + 8 + 5x = 11x + 8.','Résultat : 11x + 8.']}],
  ['Développer : je multiplie le facteur par chaque terme.','Factoriser : je cherche le facteur commun.','Réduire : je regroupe les x, puis les nombres.','Je contrôle avec une valeur de x.'],
  ['Oublier de multiplier le second terme : 4(x + 2) ≠ 4x + 2.','Additionner 3x et 5.','Mal factoriser : 6x + 9 = 3(2x + 3), pas 6(x + 9).'],
  ['k(a + b) = ka + kb.','Factoriser = retrouver le facteur commun.','Réduire : regrouper les termes de même nature.']),
 g:mix([d=>{const k=R(2,9),a=R(1,6),b=R(1,9),s=P([1,-1]);return ch(`Développe : <b>${k}(${lin(a,s*b)})</b>`,lin(k*a,s*k*b),[lin(k*a,s*b),lin(a,s*k*b),lin(k*a,-s*k*b)],{expl:`${k} × ${mono(a,'x')} = ${mono(k*a,'x')} et ${k} × ${b} = ${k*b} : <b>${lin(k*a,s*k*b)}</b>.`,hint:'Multiplie chaque terme.'});},3],
  [d=>{const k=R(2,9);let a=R(1,6),b=R(1,9);while(gcd(a,b)!==1)b=R(1,9);return ch(`Factorise : <b>${lin(k*a,k*b)}</b>`,`${k}(${lin(a,b)})`,[`${k}(${lin(k*a,b)})`,`${k*a}(x + ${k*b})`,`${k}(${lin(a,k*b)})`],{expl:`${k} est un facteur commun à ${mono(k*a,'x')} et ${k*b} : <b>${k}(${lin(a,b)})</b>.`,hint:'Cherche le nombre qui divise les deux termes.'});},2],
  [d=>{const a=R(1,9),b=R(1,9),c=R(1,9),e=R(1,9);return ch(`Réduis : <b>${mono(a,'x')} + ${b} + ${mono(c,'x')} + ${e}</b>`,lin(a+c,b+e),[lin(a+c+b+e,0),lin(a+b,c+e),`${a+c+b+e}`],{expl:`x : ${a} + ${c} = ${a+c} ; nombres : ${b} + ${e} = ${b+e} → <b>${lin(a+c,b+e)}</b>.`,hint:'Regroupe ce qui se ressemble.'});},2],
  [d=>{const k=R(2,9),a=R(11,99),b=R(1,9);return num(`Calcule astucieusement ${k} × ${a} + ${k} × ${b}.`,k*(a+b),{expl:`${k} × ${a} + ${k} × ${b} = ${k} × (${a} + ${b}) = ${k} × ${a+b} = <b>${k*(a+b)}</b>.`,hint:'Factorise par le nombre commun.'});},1],
  [bank([['Pourquoi la somme de trois entiers consécutifs est-elle toujours un multiple de 3 ?','n + (n + 1) + (n + 2) = 3n + 3 = 3(n + 1)',['parce que 1 + 2 + 3 = 6','parce que 3 est impair','parce que n est pair'],'Le calcul littéral démontre la propriété pour tout n.',3],{tf:'3x + 5 = 8x.',v:false,e:'On ne peut pas additionner 3x et 5 : ce ne sont pas des termes de même nature.'}]),1])},

/* ======================= 5h ======================= */
{id:'5h',name:'Équations simples et inconnue',icon:'❓',domain:'Nombres et calculs',
 refs:[REF,PRG+' — 5e, « Calcul littéral et algébrique » : donner à la lettre le statut d’inconnue ; modéliser par ax = c ou x + b = c ; résoudre par des méthodes arithmétiques (opérations inverses)'],
 tip:'Pour x + b = c, fais l’opération inverse : x = c − b. Pour ax = c, divise : x = c ÷ a.',
 c:C(`« J’ai un nombre ; si j’ajoute 17, j’obtiens 52. Quel est ce nombre ? » On peut écrire x + 17 = 52 : la lettre x représente un nombre <b>inconnu</b> qu’on cherche. Al-Khwarizmi appelait déjà l’inconnue « la chose ».`,
  [T('Équations du type x + b = c',`<p>Pour compléter une addition à trou, on utilise une <b>soustraction</b> : x + 17 = 52 donne x = 52 − 17 = <b>35</b>.</p><p>De même x − 8 = 15 donne x = 15 + 8 = 23.</p>`),
   T('Équations du type ax = c',`<p>Pour compléter une multiplication à trou, on utilise une <b>division</b> : 6x = 42 donne x = 42 ÷ 6 = <b>7</b>.</p><p>3x = 7 donne x = 7/3 (le quotient n’est pas toujours un décimal).</p><p>On vérifie toujours en remplaçant : 6 × 7 = 42 ✔.</p>`)],
  [{q:'Un livre et un stylo coûtent ensemble 18,50 €. Le stylo coûte 2,30 €. Prix du livre ?',s:['Soit x le prix du livre : x + 2,30 = 18,50.','x = 18,50 − 2,30.','x = 16,20 : le livre coûte 16,20 €.']}],
  ['Je repère l’opération appliquée à x.','J’utilise l’opération inverse.','Je calcule x.','Je vérifie en remplaçant x dans l’équation.'],
  ['Ajouter au lieu de soustraire : x + 17 = 52 ne donne pas 69.','Multiplier au lieu de diviser : 6x = 42 ne donne pas 252.','Oublier de vérifier.'],
  ['x + b = c ⇔ x = c − b.','ax = c ⇔ x = c ÷ a.','On vérifie toujours la solution.']),
 g:mix([d=>{const x=R(1,d===1?50:300),b=R(1,d===1?50:200);return num(`Résous : x + ${b} = ${x+b}. x = ?`,x,{expl:`x = ${x+b} − ${b} = <b>${x}</b>.`,hint:'Soustrais.'});},3],
  [d=>{const a=R(2,12),x=R(1,15);return num(`Résous : ${a}x = ${a*x}. x = ?`,x,{expl:`x = ${a*x} ÷ ${a} = <b>${x}</b>.`,hint:'Divise.'});},3],
  [d=>{const x=R(5,60),b=R(1,30);return num(`Résous : x − ${b} = ${nf(x-b)}. x = ?`,x,{expl:`x = ${nf(x-b)} + ${b} = <b>${x}</b>.`,hint:'Ajoute.'});},2],
  [d=>{const p=R(5,40),s=R(2,15);return num(`Un livre et un cahier coûtent ensemble ${p+s} €. Le cahier coûte ${s} €. Quel est le prix du livre ?`,p,{unit:'€',expl:`x + ${s} = ${p+s} donc x = ${p+s} − ${s} = <b>${p} €</b>.`,hint:'Écris x + prix du cahier = total.'});},2],
  [d=>{const n=R(2,9),u=R(2,12);return num(`${n} paquets identiques pèsent ensemble ${n*u} kg. Combien pèse un paquet ?`,u,{unit:'kg',expl:`${n}x = ${n*u} donc x = ${n*u} ÷ ${n} = <b>${u} kg</b>.`,hint:'Écris n × x = total.'});},1])},

/* ======================= 5i ======================= */
{id:'5i',name:'Repérage sur une droite et dans le plan',icon:'📍',domain:'Espace et géométrie',
 refs:[REF,PRG+' — 5e, « Repérage sur une droite et dans le plan » : lire et placer des abscisses sur une droite graduée, des coordonnées dans un repère orthogonal'],
 tip:'Coordonnées (x ; y) : on lit d’abord l’abscisse sur l’axe horizontal, puis l’ordonnée sur l’axe vertical. « On avance, puis on monte. »',
 c:C(`Sur une carte au trésor, « 3 pas à droite et 2 pas vers le haut » mène au coffre. En mathématiques, on repère un point avec des nombres : son <b>abscisse</b> sur une droite graduée, ses <b>coordonnées</b> dans un repère du plan.`,
  [T('Droite graduée',`<p>Une droite graduée a une origine (0), un sens et une unité. Chaque point a une <b>abscisse</b>, qui peut être négative : à gauche de 0, l’abscisse est négative.</p><p>Pour lire une abscisse, on repère le <b>pas</b> de la graduation : si 4 graduations séparent 0 et 2, chaque graduation vaut 0,5.</p>`),
   T('Repère du plan',`<p>Un repère orthogonal est formé de deux droites graduées perpendiculaires qui se coupent à l’origine O. Le point A(3 ; −2) a pour <b>abscisse</b> 3 et pour <b>ordonnée</b> −2.</p><p>Pour placer A : on part de O, on se déplace de 3 sur l’axe horizontal (vers la droite), puis de 2 vers le bas.</p>`)],
  [{q:'Placer B(−4 ; 1) dans un repère.',s:['Abscisse −4 : on va de 4 unités vers la gauche.','Ordonnée 1 : on monte d’une unité.','Le point B est en haut à gauche de l’origine.']}],
  ['Je repère l’origine et l’unité (ou le pas).','Je lis l’abscisse sur l’axe horizontal.','Je lis l’ordonnée sur l’axe vertical.','J’écris (abscisse ; ordonnée).'],
  ['Inverser abscisse et ordonnée.','Compter les traits au lieu des intervalles.','Oublier le signe moins à gauche ou en bas de l’origine.'],
  ['Abscisse : position sur l’axe horizontal.','Coordonnées : (abscisse ; ordonnée).','Gauche ou bas de l’origine : nombre négatif.']),
 g:mix([d=>{const step=P(d===1?[1,2]:[0.5,0.25,5,10]);const start=-3*step,i=R(0,8);const val=Math.round((start+i*step)*1000)/1000;return num(`${H.SVG.line(start,start+8*step,step,val,[start,0,start+8*step])}Quelle est l’abscisse du point marqué ?`,val,{expl:`Le pas est ${nf(step)} : l’abscisse est <b>${nf(val)}</b>.`,hint:'Repère 0 et la valeur d’une graduation.'});},3],
  [d=>{const a=P([1,-1,2,0.5]),b=R(-2,2);const xs=[-2,-1,0,1,2].filter(x=>Number.isInteger(a*x+b)&&Math.abs(a*x+b)<=5);const x=P(xs);return multiP(`${graph([[a,b]])}Quelles sont les coordonnées du point de la droite d’abscisse ${nf(x)} ?`,x,a*x+b);},2],
  [d=>{const x=R(1,5)*P([1,-1]),y=R(1,5)*P([1,-1]);const Q=['à droite et en haut','à droite et en bas','à gauche et en haut','à gauche et en bas'];const good=`${x>0?'à droite':'à gauche'} et ${y>0?'en haut':'en bas'}`;return ch(`Où se trouve le point C(${nf(x)} ; ${nf(y)}) par rapport à l’origine ?`,good,Q.filter(q=>q!==good),{expl:`Abscisse ${nf(x)} : ${x>0?'droite':'gauche'} ; ordonnée ${nf(y)} : ${y>0?'haut':'bas'}.`,hint:'L’abscisse se lit à l’horizontale.'});},2],
  [bank([['Le point (0 ; −3) est situé…','sur l’axe des ordonnées, sous l’origine',['sur l’axe des abscisses, à gauche','à l’origine','en haut à droite'],'Abscisse nulle : sur l’axe vertical ; ordonnée négative : en bas.'],{tf:'Les points (1 ; 4) et (4 ; 1) sont le même point.',v:false,e:'L’ordre des coordonnées compte.'}]),1])},

/* ======================= 5j ======================= */
{id:'5j',name:'Prismes, cylindres, patrons et volumes',icon:'🧊',domain:'Espace et géométrie',
 refs:[REF,PRG+' — 5e, « Représentation de l’espace » : perspective cavalière et patrons du pavé, du prisme droit, du cylindre ; volumes du cube, du pavé, du prisme droit, du cylindre ; aire du disque ; unités de volume et de capacité'],
 tip:'Prisme droit et cylindre : volume = aire de la base × hauteur. Pour le cylindre, la base est un disque d’aire π × r².',
 c:C(`Une boîte de chocolats triangulaire, une boîte de conserve, une brique de lait : ce sont des <b>prismes droits</b> et des <b>cylindres</b>. Quelle quantité peuvent-ils contenir ? On calcule leur <b>volume</b>.`,
  [T('Solides et patrons',`<p>Un <b>prisme droit</b> a deux bases polygonales superposables et parallèles, et des faces latérales rectangulaires. Le pavé droit est un prisme particulier.</p><p>Un <b>cylindre de révolution</b> a deux bases qui sont des disques ; son patron est formé de deux disques et d’un rectangle dont une dimension est le périmètre du disque (2πr).</p><p>En perspective cavalière, les arêtes cachées sont en pointillés.</p>`),
   T('Volumes et unités',`<p>Pavé : V = L × l × h. Cube : V = c³. <b>Prisme droit : V = aire de la base × hauteur</b>.</p><p>Aire du disque : <b>π × r²</b>. <b>Cylindre : V = π × r² × h</b>.</p><p>Unités : 1 dm³ = 1 L ; 1 cm³ = 1 mL ; 1 m³ = 1 000 L.</p>`)],
  [{q:'Une boîte de conserve a un rayon de 4 cm et une hauteur de 10 cm. Volume ? Contenance en litres ?',s:['Aire de la base : π × 4² = 16π cm².','V = 16π × 10 = 160π ≈ 502,7 cm³.','≈ 503 cm³ ≈ 0,5 L (1 L = 1 000 cm³).']}],
  ['J’identifie le solide et sa base.','Je calcule l’aire de la base (rectangle, triangle, disque).','Je multiplie par la hauteur du solide.','Je convertis si on demande une contenance.'],
  ['Prendre le diamètre au lieu du rayon.','Confondre aire de la base et périmètre de la base.','Oublier que 1 L = 1 dm³ = 1 000 cm³.'],
  ['Prisme droit, cylindre : V = aire de base × hauteur.','Disque : π × r².','1 dm³ = 1 L ; 1 cm³ = 1 mL.']),
 g:mix([d=>{const L=R(2,12),l=R(2,10),h=R(2,10);return num(`Volume d’un pavé droit de ${L} cm × ${l} cm × ${h} cm ?`,L*l*h,{unit:'cm³',expl:`${L} × ${l} × ${h} = <b>${L*l*h} cm³</b>.`,hint:'Longueur × largeur × hauteur.'});},2],
  [d=>{const b=R(2,10),hb=2*R(1,5),h=R(2,12);return num(`Un prisme droit a pour base un triangle de base ${b} cm et de hauteur ${hb} cm ; la hauteur du prisme est ${h} cm. Volume ?`,b*hb/2*h,{unit:'cm³',expl:`Aire de la base : ${b} × ${hb} ÷ 2 = ${b*hb/2} cm² ; V = ${b*hb/2} × ${h} = <b>${b*hb/2*h} cm³</b>.`,hint:'Aire du triangle × hauteur du prisme.'});},2],
  [d=>{const r=R(1,8),h=R(2,15);const v=Math.round(Math.PI*r*r*h);return num(`Volume d’un cylindre de rayon ${r} cm et de hauteur ${h} cm, arrondi au cm³ ?`,v,{unit:'cm³',expl:`V = π × ${r}² × ${h} = ${r*r*h}π ≈ <b>${v} cm³</b>.`,hint:'π × r² × h.'});},3],
  [d=>{const r=R(1,10);const a=Math.round(Math.PI*r*r*10)/10;return num(`Aire d’un disque de rayon ${r} cm, arrondie au dixième ?`,a,{unit:'cm²',tol:0.0501,expl:`π × ${r}² = ${r*r}π ≈ <b>${nf(a)} cm²</b>.`,hint:'π × r².'});},2],
  [d=>{const v=P([[3000,'cm³','L',3],[2,'L','cm³',2000],[0.75,'L','cm³',750],[5,'dm³','L',5],[1.2,'m³','L',1200],[250,'mL','cm³',250]]);return num(`Convertis ${nf(v[0])} ${v[1]} en ${v[2]}.`,v[3],{unit:v[2],expl:`1 L = 1 dm³ = 1 000 cm³ ; 1 m³ = 1 000 L ; 1 mL = 1 cm³. Résultat : <b>${nf(v[3])} ${v[2]}</b>.`,hint:'1 L = 1 dm³.'});},2],
  [bank([['Combien de faces a un prisme droit à base triangulaire ?','5',['6','3','9'],'2 bases + 3 faces latérales.'],['Le patron d’un cylindre comprend…','deux disques et un rectangle',['deux rectangles et un disque','trois disques','un disque et un triangle'],'La surface latérale se déroule en rectangle.']]),1])},

/* ======================= 5k ======================= */
{id:'5k',name:'Symétrie centrale : le demi-tour',icon:'🔄',domain:'Espace et géométrie',
 refs:[REF,PRG+' — 5e, « Transformations » : définir le demi-tour (symétrie centrale) et connaître ses propriétés'],
 tip:'Symétrique de A par rapport à O : trace la droite (AO), puis reporte la longueur OA de l’autre côté de O : O est le milieu de [AA′].',
 c:C(`Tourne ta feuille d’un demi-tour autour d’une punaise plantée en O : chaque dessin arrive à une nouvelle place. Cette transformation s’appelle le <b>demi-tour</b>, ou <b>symétrie centrale</b> de centre O.`,
  [T('Définition',`<p>Le symétrique d’un point A par rapport à O est le point A′ tel que <b>O est le milieu de [AA′]</b>. Le symétrique de O est O lui-même.</p><p>C’est un demi-tour (rotation de 180°) autour de O. À ne pas confondre avec la symétrie axiale (pliage le long d’une droite).</p>`),
   T('Propriétés',`<p>La symétrie centrale <b>conserve</b> les longueurs, les angles, les aires et l’alignement. Le symétrique d’une droite est une droite <b>parallèle</b> ; le symétrique d’un cercle de centre C est un cercle de même rayon dont le centre est le symétrique de C.</p><p>Une figure a un <b>centre de symétrie</b> si elle est sa propre image par un demi-tour : le parallélogramme (centre : point d’intersection des diagonales), le cercle, la lettre S, la lettre Z.</p>`)],
  [{q:'A′ est le symétrique de A par rapport à O, et OA = 3,5 cm. Que vaut AA′ ?',s:['O est le milieu de [AA′].','Donc OA′ = OA = 3,5 cm.','AA′ = 2 × 3,5 = 7 cm.']}],
  ['Je trace la droite qui passe par le point et le centre.','Je reporte la même distance de l’autre côté du centre.','Je vérifie que le centre est le milieu du segment.','Pour une figure, je construis le symétrique de chaque sommet.'],
  ['Construire un symétrique axial au lieu d’un symétrique central.','Reporter une distance différente de l’autre côté.','Croire que l’image d’une droite est perpendiculaire à la droite.'],
  ['A′ symétrique de A par rapport à O ⇔ O milieu de [AA′].','La symétrie centrale conserve longueurs, angles, aires.','L’image d’une droite est une droite parallèle.']),
 g:mix([d=>{const ox=R(-2,2),oy=R(-2,2);let x=R(-4,4),y=R(-4,4);if(x===ox&&y===oy)x+=2;return multiP(`Dans un repère, A(${nf(x)} ; ${nf(y)}) et O(${nf(ox)} ; ${nf(oy)}). Quelles sont les coordonnées du symétrique de A par rapport à O ?`,2*ox-x,2*oy-y);},2],
  [d=>{const a=R(2,9)+P([0,0.5]);return num(`A′ est le symétrique de A par rapport à O, avec OA = ${nf(a)} cm. Que vaut AA′ ?`,2*a,{unit:'cm',expl:`O est le milieu de [AA′] : AA′ = 2 × ${nf(a)} = <b>${nf(2*a)} cm</b>.`,hint:'O est le milieu.'});},2],
  [d=>{const f=P([['un parallélogramme','oui'],['un cercle','oui'],['un rectangle','oui'],['un triangle équilatéral','non'],['la lettre Z','oui'],['la lettre S','oui'],['la lettre A','non'],['un trapèze non parallélogramme','non'],['la lettre E','non'],['la lettre N','oui']]);return ch(`<b>${f[0].charAt(0).toUpperCase()+f[0].slice(1)}</b> a-t-${f[0].startsWith('la')?'elle':'il'} un centre de symétrie ?`,f[1]==='oui'?'Oui':'Non',[f[1]==='oui'?'Non':'Oui'],{expl:f[1]==='oui'?`${f[0].charAt(0).toUpperCase()+f[0].slice(1)} se superpose à ${f[0].startsWith('la')?'elle':'lui'}-même après un demi-tour.`:`Après un demi-tour, ${f[0]} ne se superpose pas à ${f[0].startsWith('la')?'elle':'lui'}-même.`,hint:'Imagine un demi-tour de la figure.'});},2],
  [bank([['Le symétrique d’une droite par une symétrie centrale est…','une droite parallèle',['une droite perpendiculaire','un cercle','un point'],'La symétrie centrale transforme une droite en une droite parallèle.'],['La symétrie centrale conserve…','les longueurs et les angles',['seulement les angles','seulement les longueurs','rien'],'Le demi-tour ne déforme pas la figure.'],{tf:'Une symétrie centrale est un demi-tour.',v:true,e:'C’est une rotation de 180°.'}]),1])},

/* ======================= 5l ======================= */
{id:'5l',name:'Angles et parallélisme',icon:'📐',domain:'Espace et géométrie',
 refs:[REF,PRG+' — 5e, « Angles » : vocabulaire (adjacents, opposés par le sommet, supplémentaires) ; caractériser le parallélisme par les angles alternes-internes et correspondants'],
 tip:'Deux angles supplémentaires font 180° ; opposés par le sommet, ils sont égaux ; avec deux parallèles, alternes-internes et correspondants sont égaux.',
 c:C(`Les voies ferrées sont parallèles et un chemin les traverse en biais. Les angles formés aux deux croisements sont-ils égaux ? Oui, si les voies sont bien parallèles : c’est une façon de <b>reconnaître le parallélisme</b> par les angles.`,
  [T('Vocabulaire',`<p>Angle droit : 90° ; angle plat : 180° ; aigu : moins de 90° ; obtus : entre 90° et 180°.</p><p>Deux angles <b>adjacents</b> ont le même sommet, un côté commun et sont de part et d’autre de ce côté. Deux angles <b>supplémentaires</b> ont une somme de 180° ; <b>complémentaires</b>, 90°.</p><p>Deux angles <b>opposés par le sommet</b> sont égaux.</p>`),
   T('Parallèles et sécante',`<p>Une sécante coupe deux droites (d) et (d′). Elle forme des angles <b>alternes-internes</b> (entre les deux droites, de part et d’autre de la sécante) et <b>correspondants</b> (même position aux deux intersections).</p><p>Si (d) // (d′), ces angles sont <b>égaux</b>. Réciproquement, si deux angles alternes-internes (ou correspondants) sont égaux, alors (d) // (d′).</p>`)],
  [{q:'(d) // (d′). La sécante forme un angle de 115° avec (d). Quels sont l’angle correspondant sur (d′) et son supplémentaire ?',s:['(d) // (d′) : les angles correspondants sont égaux → 115°.','Supplémentaire : 180° − 115° = 65°.','Les angles alternes-internes valent donc 115° ou 65° selon leur position.']}],
  ['Je repère la sécante et les deux droites.','Je nomme la position des angles (alternes-internes, correspondants, opposés).','J’applique la propriété (égaux) ou la somme (180°).','Je justifie par la propriété du cours.'],
  ['Confondre angles alternes-internes et correspondants.','Utiliser l’égalité des angles sans savoir que les droites sont parallèles.','Oublier qu’un angle plat vaut 180°.'],
  ['Opposés par le sommet → égaux.','Supplémentaires → somme 180°.','Parallèles ⇔ alternes-internes (ou correspondants) égaux.']),
 g:mix([d=>{const a=R(15,165);return num(`Un angle mesure ${a}°. Combien mesure son supplémentaire ?`,180-a,{unit:'°',expl:`180 − ${a} = <b>${180-a}°</b>.`,hint:'Supplémentaires : somme 180°.'});},2],
  [d=>{const a=R(10,80);return num(`Un angle mesure ${a}°. Combien mesure son complémentaire ?`,90-a,{unit:'°',expl:`90 − ${a} = <b>${90-a}°</b>.`,hint:'Complémentaires : somme 90°.'});},1],
  [d=>{const a=R(20,160);const k=P([['alterne-interne',a],['correspondant',a],['opposé par le sommet',a],['supplémentaire adjacent',180-a]]);return num(`Deux droites parallèles sont coupées par une sécante. Un angle mesure ${a}°. Combien mesure l’angle ${k[0]} à cet angle ?`,k[1],{unit:'°',expl:k[0]==='supplémentaire adjacent'?`180 − ${a} = <b>${180-a}°</b>.`:`Ces angles sont égaux : <b>${a}°</b>.`,hint:'Égaux ou supplémentaires ?'});},3],
  [d=>{const a=R(40,140);const b=P([a,a,a+P([2,-3,5])]);const ok=a===b;return ch(`Deux droites sont coupées par une sécante ; deux angles alternes-internes mesurent ${a}° et ${b}°. Les droites sont-elles parallèles ?`,ok?'Oui':'Non',[ok?'Non':'Oui'],{expl:ok?'Les angles alternes-internes sont égaux : les droites sont parallèles.':'Les angles alternes-internes ne sont pas égaux : les droites ne sont pas parallèles.',hint:'Compare les deux angles.'});},2],
  [d=>{const a=R(1,179);const t=a<90?'aigu':a===90?'droit':'obtus';return ch(`Un angle de ${a}° est…`,t,['aigu','droit','obtus','plat'].filter(x=>x!==t),{expl:`${a}° ${a<90?'&lt; 90°':a===90?'= 90°':'est entre 90° et 180°'} : angle <b>${t}</b>.`,hint:'Compare à 90°.'});},1])},

/* ======================= 5m ======================= */
{id:'5m',name:'Triangles : somme des angles et constructions',icon:'🔺',domain:'Espace et géométrie',
 refs:[REF,PRG+' — 5e, « Triangles » : somme des angles (et sa démonstration), constructions à partir de données partielles, médiatrices et cercle circonscrit'],
 tip:'Dans tout triangle, A + B + C = 180°. Pour le 3e angle : 180° − (somme des deux autres).',
 c:C(`Dessine n’importe quel triangle, découpe ses trois coins et assemble-les : ils forment toujours un angle plat ! La <b>somme des angles d’un triangle vaut 180°</b> ; on peut le démontrer avec une parallèle et les angles alternes-internes.`,
  [T('Somme des angles',`<p>Dans un triangle ABC : <b>Â + B̂ + Ĉ = 180°</b>.</p><p>Démonstration : on trace la parallèle à (BC) passant par A ; les angles alternes-internes égaux à B̂ et Ĉ forment avec Â un angle plat (180°).</p><p>Conséquences : un triangle équilatéral a trois angles de 60° ; dans un triangle rectangle, les deux angles aigus sont complémentaires (somme 90°) ; un triangle isocèle a ses deux angles à la base égaux.</p>`),
   T('Constructions et médiatrices',`<p>On construit un triangle à partir de : trois longueurs (compas) ; deux longueurs et l’angle compris ; une longueur et deux angles. Avec trois longueurs, la plus grande doit être <b>inférieure à la somme</b> des deux autres.</p><p>La <b>médiatrice</b> d’un segment est la droite perpendiculaire en son milieu ; tout point de la médiatrice est à égale distance des extrémités. Les trois médiatrices d’un triangle se coupent au centre du <b>cercle circonscrit</b>.</p>`)],
  [{q:'Un triangle ABC est isocèle en A avec Â = 40°. Calculer B̂ et Ĉ.',s:['B̂ + Ĉ = 180° − 40° = 140°.','Triangle isocèle en A : B̂ = Ĉ.','B̂ = Ĉ = 140° ÷ 2 = 70°.']}],
  ['J’écris la propriété : somme des angles = 180°.','Je remplace les angles connus.','J’utilise la nature du triangle (isocèle, rectangle, équilatéral).','Je calcule et je vérifie que la somme fait 180°.'],
  ['Oublier qu’un angle droit compte pour 90°.','Croire qu’on peut construire un triangle de côtés 2, 3 et 8.','Confondre médiatrice et médiane.'],
  ['Somme des angles d’un triangle : 180°.','Isocèle : angles à la base égaux ; équilatéral : 60° chacun.','Médiatrices concourantes au centre du cercle circonscrit.']),
 g:mix([d=>{const a=R(20,100),b=R(20,150-a);return num(`Dans un triangle, deux angles mesurent ${a}° et ${b}°. Combien mesure le troisième ?`,180-a-b,{unit:'°',expl:`180 − ${a} − ${b} = <b>${180-a-b}°</b>.`,hint:'La somme vaut 180°.'});},3],
  [d=>{const a=R(10,80);return num(`Un triangle est rectangle ; un de ses angles aigus mesure ${a}°. Combien mesure l’autre angle aigu ?`,90-a,{unit:'°',expl:`180 − 90 − ${a} = <b>${90-a}°</b>.`,hint:'Les deux angles aigus font 90° ensemble.'});},2],
  [d=>{const s=2*R(10,70);return num(`Un triangle est isocèle ; l’angle au sommet principal mesure ${s}°. Combien mesure chaque angle à la base ?`,(180-s)/2,{unit:'°',expl:`(180 − ${s}) ÷ 2 = <b>${(180-s)/2}°</b>.`,hint:'Les deux angles à la base sont égaux.'});},2],
  [d=>{const a=R(2,9),b=R(2,9);const c=P([a+b-1,a+b+R(1,4),Math.abs(a-b)+1,Math.max(a,b)]);const ok=c<a+b&&a<b+c&&b<a+c;return ch(`Peut-on construire un triangle de côtés ${a} cm, ${b} cm et ${c} cm ?`,ok?'Oui':'Non',[ok?'Non':'Oui'],{expl:ok?'La plus grande longueur est inférieure à la somme des deux autres : c’est possible.':'La plus grande longueur n’est pas inférieure à la somme des deux autres : impossible.',hint:'Compare le plus grand côté à la somme des deux autres.'});},2],
  [bank([['Tout point de la médiatrice de [AB] est…','à égale distance de A et de B',['sur le segment [AB]','plus près de A','le milieu de [AB]'],'Propriété de la médiatrice.'],['Les trois médiatrices d’un triangle se coupent au centre du…','cercle circonscrit',['cercle inscrit','triangle équilatéral','carré'],'Ce point est à égale distance des trois sommets.'],{tf:'Un triangle peut avoir deux angles droits.',v:false,e:'90 + 90 = 180 : le troisième angle serait nul.'}]),1])},

/* ======================= 5n ======================= */
{id:'5n',name:'Hauteurs, médianes et aire du triangle',icon:'📏',domain:'Espace et géométrie',
 refs:[REF,PRG+' — 5e, « Triangles » : hauteurs (concourantes), médianes, aire du triangle ; une médiane partage le triangle en deux triangles d’aires égales'],
 tip:'Aire du triangle = base × hauteur ÷ 2, où la hauteur est perpendiculaire à la base choisie (pas un côté quelconque !).',
 c:C(`Un triangle est la moitié d’un rectangle (ou d’un parallélogramme) de même base et de même hauteur. C’est pourquoi son aire vaut <b>base × hauteur ÷ 2</b>. Encore faut-il savoir ce qu’est une hauteur.`,
  [T('Hauteurs et médianes',`<p>Une <b>hauteur</b> est la droite qui passe par un sommet et qui est <b>perpendiculaire</b> au côté opposé. Les trois hauteurs d’un triangle sont concourantes (elles se coupent en un même point).</p><p>Une <b>médiane</b> joint un sommet au <b>milieu</b> du côté opposé. Une médiane partage le triangle en deux triangles de même aire (même base, même hauteur).</p>`),
   T('Aire du triangle',`<p><b>A = (b × h) ÷ 2</b>, où b est la longueur d’un côté et h la hauteur relative à ce côté.</p><p>Triangle de base 8 cm et de hauteur 5 cm : A = 8 × 5 ÷ 2 = 20 cm².</p><p>Dans un triangle rectangle, les deux côtés de l’angle droit sont base et hauteur l’un pour l’autre : côtés 6 et 4 → A = 12 cm².</p>`)],
  [{q:'Triangle ABC : BC = 12 cm, hauteur issue de A : 7 cm. Aire ?',s:['La base est [BC] et la hauteur relative à [BC] mesure 7 cm.','A = 12 × 7 ÷ 2.','A = 42 cm².']}],
  ['Je choisis un côté comme base.','Je repère la hauteur perpendiculaire à ce côté.','Je calcule base × hauteur ÷ 2.','J’écris l’unité d’aire (cm²).'],
  ['Prendre un côté non perpendiculaire à la base comme hauteur.','Oublier de diviser par 2.','Confondre médiane (milieu) et hauteur (perpendiculaire).'],
  ['Hauteur : passe par un sommet, perpendiculaire au côté opposé.','Médiane : joint un sommet au milieu du côté opposé.','Aire = base × hauteur ÷ 2.']),
 g:mix([d=>{const b=R(3,15),h=R(2,12);return num(`Aire d’un triangle de base ${b} cm et de hauteur ${h} cm ?`,b*h/2,{unit:'cm²',expl:`${b} × ${h} ÷ 2 = <b>${nf(b*h/2)} cm²</b>.`,hint:'Base × hauteur ÷ 2.'});},3],
  [d=>{const a=R(2,12),b=R(2,12);return num(`Aire d’un triangle rectangle dont les côtés de l’angle droit mesurent ${a} cm et ${b} cm ?`,a*b/2,{unit:'cm²',expl:`${a} × ${b} ÷ 2 = <b>${nf(a*b/2)} cm²</b>.`,hint:'Les côtés de l’angle droit sont base et hauteur.'});},2],
  [d=>{const b=2*R(2,9),A=b*R(2,9)/2;return num(`Un triangle a une aire de ${A} cm² et une base de ${b} cm. Quelle est la hauteur relative à cette base ?`,2*A/b,{unit:'cm',expl:`h = 2 × ${A} ÷ ${b} = <b>${2*A/b} cm</b>.`,hint:'A = b × h ÷ 2 donc h = 2A ÷ b.'});},2],
  [d=>{const A=2*R(5,30);return num(`Une médiane partage un triangle d’aire ${A} cm² en deux triangles. Quelle est l’aire de chacun ?`,A/2,{unit:'cm²',expl:`Les deux triangles ont même base (moitiés égales) et même hauteur : ${A} ÷ 2 = <b>${A/2} cm²</b>.`,hint:'Une médiane partage l’aire en deux.'});},1],
  [bank([['Une hauteur d’un triangle est…','perpendiculaire au côté opposé et passe par un sommet',['la droite qui passe par le milieu d’un côté','toujours à l’intérieur du triangle','parallèle à un côté'],'Définition de la hauteur.'],['Une médiane joint un sommet…','au milieu du côté opposé',['au pied de la hauteur','au centre du cercle circonscrit','à un autre sommet'],'Définition de la médiane.']]),1])},

/* ======================= 5o ======================= */
{id:'5o',name:'Parallélogrammes et quadrilatères particuliers',icon:'▱',domain:'Espace et géométrie',
 refs:[REF,PRG+' — 5e, « Parallélogrammes » : définition, propriétés des côtés et des diagonales, parallélogrammes particuliers (rectangle, losange, carré), aire du parallélogramme'],
 tip:'Diagonales qui se coupent en leur milieu → parallélogramme ; + même longueur → rectangle ; + perpendiculaires → losange ; les deux → carré.',
 c:C(`Un quadrilatère dont les côtés opposés sont parallèles s’appelle un <b>parallélogramme</b>. Rectangle, losange et carré en sont des cas particuliers. Leurs propriétés permettent de les reconnaître… et de calculer leur aire.`,
  [T('Le parallélogramme',`<p><b>Définition</b> : un parallélogramme est un quadrilatère dont les côtés opposés sont parallèles deux à deux.</p><p><b>Propriétés</b> : ses côtés opposés ont la même longueur ; ses angles opposés sont égaux ; ses <b>diagonales se coupent en leur milieu</b> (ce point est son centre de symétrie).</p><p>Réciproquement, un quadrilatère dont les diagonales se coupent en leur milieu est un parallélogramme.</p>`),
   T('Parallélogrammes particuliers et aire',`<p><b>Rectangle</b> : parallélogramme avec un angle droit ; diagonales de même longueur.</p><p><b>Losange</b> : parallélogramme avec deux côtés consécutifs égaux ; diagonales perpendiculaires.</p><p><b>Carré</b> : à la fois rectangle et losange.</p><p>Aire du parallélogramme : <b>base × hauteur</b> (hauteur perpendiculaire à la base).</p>`)],
  [{q:'ABCD est un parallélogramme de centre O, AC = 10 cm, BD = 10 cm. Quelle est sa nature ?',s:['Ses diagonales se coupent en leur milieu (parallélogramme).','Elles ont la même longueur : 10 cm.','C’est donc un rectangle.']}],
  ['Je vérifie d’abord que c’est un parallélogramme.','J’examine ses diagonales (longueur, angle) ou ses côtés.','Je conclus avec la propriété caractéristique.','Pour l’aire, je prends la hauteur perpendiculaire à la base.'],
  ['Calculer l’aire d’un parallélogramme avec un côté oblique au lieu de la hauteur.','Croire qu’un losange a toujours des angles droits.','Oublier qu’un carré est aussi un rectangle et un losange.'],
  ['Parallélogramme : diagonales qui se coupent en leur milieu.','Rectangle : diagonales de même longueur ; losange : perpendiculaires.','Aire = base × hauteur.']),
 g:mix([d=>{const p=P([['dont les diagonales se coupent en leur milieu','un parallélogramme',['un trapèze','un cerf-volant','un triangle']],['parallélogramme dont les diagonales ont la même longueur','un rectangle',['un losange','un trapèze','un cerf-volant']],['parallélogramme dont les diagonales sont perpendiculaires','un losange',['un rectangle','un trapèze','un cerf-volant']],['parallélogramme qui a un angle droit','un rectangle',['un losange','un trapèze','un cerf-volant']],['parallélogramme dont deux côtés consécutifs ont la même longueur','un losange',['un rectangle','un trapèze','un triangle']],['parallélogramme dont les diagonales sont perpendiculaires et de même longueur','un carré',['un rectangle seulement','un losange seulement','un trapèze']]]);return ch(`Un quadrilatère ${p[0].startsWith('parall')?'qui est un ':''}${p[0]} est…`,p[1],p[2],{expl:`Propriété caractéristique : c’est <b>${p[1]}</b>.`,hint:'Pense aux propriétés des diagonales.'});},3],
  [d=>{const b=R(3,15),h=R(2,10);return num(`Aire d’un parallélogramme de base ${b} cm et de hauteur ${h} cm ?`,b*h,{unit:'cm²',expl:`${b} × ${h} = <b>${b*h} cm²</b>.`,hint:'Base × hauteur.'});},2],
  [d=>{const a=R(30,150);return num(`ABCD est un parallélogramme et Â = ${a}°. Combien mesure B̂ ?`,180-a,{unit:'°',expl:`Deux angles consécutifs d’un parallélogramme sont supplémentaires : 180 − ${a} = <b>${180-a}°</b>.`,hint:'Angles consécutifs : somme 180°.'});},2],
  [d=>{const ac=2*R(2,9);return num(`ABCD est un parallélogramme de centre O et AC = ${ac} cm. Combien mesure AO ?`,ac/2,{unit:'cm',expl:`Les diagonales se coupent en leur milieu : AO = ${ac} ÷ 2 = <b>${ac/2} cm</b>.`,hint:'O est le milieu de [AC].'});},1],
  [bank([{tf:'Un carré est un losange.',v:true,e:'Il a quatre côtés de même longueur.'},{tf:'Tout rectangle est un carré.',v:false,e:'Un rectangle n’a pas forcément ses quatre côtés égaux.'},['Les côtés opposés d’un parallélogramme sont…','parallèles et de même longueur',['perpendiculaires','de longueurs différentes','toujours égaux aux diagonales'],'Définition et propriété.']]),1])},

/* ======================= 5p ======================= */
{id:'5p',name:'Aires composées et conversions',icon:'📐',domain:'Grandeurs et mesures',
 refs:[REF,PRG+' — 5e, « Parallélogrammes » : aire de figures complexes ; résoudre des problèmes de conversions d’unités de longueur et d’aire'],
 tip:'Entre deux unités d’aire voisines, on multiplie ou divise par 100 (pas par 10) : 1 m² = 100 dm² = 10 000 cm².',
 c:C(`Pour carreler une pièce en forme de L, il faut connaître son aire. On la <b>découpe</b> en figures simples (rectangles, triangles) dont on additionne les aires, ou on calcule l’aire d’un grand rectangle et on <b>retire</b> le morceau manquant.`,
  [T('Aires de référence',`<p>Rectangle : L × l ; carré : c × c ; triangle : b × h ÷ 2 ; parallélogramme : b × h ; disque : π × r².</p><p>Figure composée : on additionne (ou on soustrait) les aires des morceaux.</p>`),
   T('Unités d’aire',`<p>1 cm² est l’aire d’un carré de 1 cm de côté. Un carré de 1 m de côté contient 100 × 100 = 10 000 carrés de 1 cm : <b>1 m² = 10 000 cm²</b>.</p><p>Entre deux unités voisines (km², hm², dam², m², dm², cm², mm²) : × 100 ou ÷ 100. 1 hectare (ha) = 10 000 m².</p>`)],
  [{q:'Une pièce en L : un rectangle de 6 m × 4 m auquel on a retiré un coin carré de 2 m de côté. Aire ?',s:['Grand rectangle : 6 × 4 = 24 m².','Coin retiré : 2 × 2 = 4 m².','Aire : 24 − 4 = 20 m².']}],
  ['Je découpe la figure en morceaux simples (ou je la complète).','Je calcule l’aire de chaque morceau dans la même unité.','J’additionne ou je soustrais.','Je convertis si nécessaire (× 100 par rang).'],
  ['Convertir des aires avec × 10 au lieu de × 100.','Mélanger des m et des cm dans un même calcul.','Compter deux fois une partie commune.'],
  ['Figure composée : découper ou compléter.','1 m² = 100 dm² = 10 000 cm².','1 ha = 10 000 m².']),
 g:mix([d=>{const L=R(5,12),l=R(4,10),c=R(1,Math.min(L,l)-2);return num(`Un rectangle de ${L} m × ${l} m dont on a retiré un carré de ${c} m de côté dans un coin. Aire de la figure ?`,L*l-c*c,{unit:'m²',expl:`${L} × ${l} − ${c} × ${c} = ${L*l} − ${c*c} = <b>${L*l-c*c} m²</b>.`,hint:'Grand rectangle moins le carré.'});},2],
  [d=>{const L=R(4,10),l=R(2,8),h=2*R(1,4);return num(`Une figure est formée d’un rectangle de ${L} cm × ${l} cm surmonté d’un triangle de base ${L} cm et de hauteur ${h} cm. Aire totale ?`,L*l+L*h/2,{unit:'cm²',expl:`${L} × ${l} + ${L} × ${h} ÷ 2 = ${L*l} + ${L*h/2} = <b>${L*l+L*h/2} cm²</b>.`,hint:'Rectangle + triangle.'});},2],
  [d=>{const c=P([['m²','dm²',100],['m²','cm²',10000],['dm²','cm²',100],['cm²','mm²',100],['ha','m²',10000],['km²','ha',100]]);const v=P([1,2,3,5,0.5,1.5,12]);const inv=Math.random()<.5;return inv?num(`Convertis ${nf(v*c[2])} ${c[1]} en ${c[0]}.`,v,{unit:c[0],expl:`1 ${c[0]} = ${nf(c[2])} ${c[1]} : ${nf(v*c[2])} ÷ ${nf(c[2])} = <b>${nf(v)} ${c[0]}</b>.`,hint:'Entre unités d’aire voisines : × 100.'}):num(`Convertis ${nf(v)} ${c[0]} en ${c[1]}.`,v*c[2],{unit:c[1],expl:`1 ${c[0]} = ${nf(c[2])} ${c[1]} : ${nf(v)} × ${nf(c[2])} = <b>${nf(v*c[2])} ${c[1]}</b>.`,hint:'Entre unités d’aire voisines : × 100.'});},3],
  [d=>{const c=P([['m','cm',100],['km','m',1000],['m','mm',1000],['dm','cm',10]]);const v=P([2,3.5,0.4,12,1.25]);return num(`Convertis ${nf(v)} ${c[0]} en ${c[1]}.`,Math.round(v*c[2]*1000)/1000,{unit:c[1],expl:`1 ${c[0]} = ${c[2]} ${c[1]} : <b>${nf(Math.round(v*c[2]*1000)/1000)} ${c[1]}</b>.`,hint:'Longueurs : × 10 par rang.'});},1],
  [bank([{tf:'1 m² = 100 cm².',v:false,e:'1 m² = 10 000 cm² (100 × 100).'},['Un hectare correspond à l’aire d’un carré de…','100 m de côté',['10 m de côté','1 km de côté','1 000 m de côté'],'100 m × 100 m = 10 000 m².',2]]),1])},

/* ======================= 5q ======================= */
{id:'5q',name:'Statistiques : effectifs, fréquences et graphiques',icon:'📊',domain:'Organisation et gestion de données',
 refs:[REF,PRG+' — 5e, « Statistiques » : recueillir et organiser des données, effectifs et fréquences, lire et représenter (tableaux, diagrammes en barres et circulaires, graphiques)'],
 tip:'Fréquence = effectif ÷ effectif total. Dans un diagramme circulaire, l’angle d’un secteur = fréquence × 360°.',
 c:C(`Ta classe a répondu à la question « Comment viens-tu au collège ? ». Pour présenter les réponses clairement, on compte les <b>effectifs</b>, on calcule les <b>fréquences</b> et on choisit un <b>graphique</b> adapté.`,
  [T('Effectifs et fréquences',`<p>L’<b>effectif</b> d’une valeur est le nombre de fois où elle apparaît ; l’effectif total est le nombre de données.</p><p>La <b>fréquence</b> = effectif ÷ effectif total ; elle s’écrit en fraction, en décimal ou en pourcentage : 6 élèves sur 24 → 6/24 = 0,25 = 25 %. La somme des fréquences vaut 1 (100 %).</p>`),
   T('Représentations',`<p><b>Diagramme en barres</b> : la hauteur de chaque barre est proportionnelle à l’effectif. <b>Diagramme circulaire</b> : il montre la répartition d’un tout ; un secteur qui représente 25 % mesure 25 % de 360° = 90°. <b>Graphique cartésien</b> : il montre une évolution (température au fil des heures).</p><p>On choisit la représentation selon ce qu’on veut mettre en avant.</p>`)],
  [{q:'Sur 40 élèves, 10 viennent à pied. Fréquence ? Angle dans un diagramme circulaire ?',s:['Fréquence : 10 ÷ 40 = 0,25 = 25 %.','Angle : 0,25 × 360° = 90°.','Le secteur « à pied » est un quart du disque.']}],
  ['Je compte les effectifs.','Je calcule l’effectif total.','Fréquence = effectif ÷ total (en %, × 100).','Je choisis et je construis un graphique adapté.'],
  ['Diviser par le nombre de catégories au lieu de l’effectif total.','Oublier qu’un diagramme circulaire représente des parts d’un tout.','Additionner des fréquences dont la somme dépasse 100 %.'],
  ['Fréquence = effectif ÷ effectif total.','Somme des fréquences = 1.','Angle d’un secteur = fréquence × 360°.']),
 g:mix([d=>{const cats=pickN(['vélo','bus','à pied','voiture','trottinette'],3);const e=cats.map(()=>R(2,15));const tot=e.reduce((a,b)=>a+b,0);return num(`Sondage : ${cats.map((c,i)=>`${c} ${e[i]}`).join(', ')}. Combien de réponses en tout ?`,tot,{expl:`${e.join(' + ')} = <b>${tot}</b>.`,hint:'Additionne les effectifs.'});},2],
  [d=>{const tot=P([20,25,40,50]),e=R(2,tot/2);return num(`Sur ${tot} élèves, ${e} pratiquent la natation. Quelle est la fréquence, en pourcentage ?`,e/tot*100,{unit:'%',expl:`${e} ÷ ${tot} = ${nf(e/tot)} = <b>${nf(e/tot*100)} %</b>.`,hint:'Effectif ÷ total × 100.'});},3],
  [d=>{const p=P([10,20,25,40,50,75,12.5,5]);return num(`Dans un diagramme circulaire, quel angle correspond à ${nf(p)} % ?`,p*3.6,{unit:'°',expl:`${nf(p)} % de 360° = ${nf(p/100)} × 360 = <b>${nf(p*3.6)}°</b>.`,hint:'Fréquence × 360°.'});},2],
  [d=>{const t=P([['montrer l’évolution de la température au cours d’une journée','un graphique cartésien'],['montrer la répartition des élèves d’une classe selon leur moyen de transport (parts d’un tout)','un diagramme circulaire'],['comparer le nombre de livres empruntés chaque mois','un diagramme en barres']]);return ch(`Quel graphique choisir pour ${t[0]} ?`,t[1],['un graphique cartésien','un diagramme circulaire','un diagramme en barres'].filter(x=>x!==t[1]),{expl:`Pour ${t[0]}, on choisit <b>${t[1]}</b>.`,hint:'Évolution, parts d’un tout ou comparaison ?'});},1],
  [bank([{tf:'La somme de toutes les fréquences d’une série vaut 100 %.',v:true,e:'Toutes les parts réunies forment le tout.'},['Une fréquence de 0,4 correspond à…','40 %',['4 %','0,4 %','400 %'],'0,4 × 100 = 40.']]),1])},

/* ======================= 5r ======================= */
{id:'5r',name:'Moyenne simple et interprétation',icon:'⚖️',domain:'Organisation et gestion de données',
 refs:[REF,PRG+' — 5e, « Statistiques » : calculer et interpréter la moyenne simple d’une série de données'],
 tip:'Moyenne = somme de toutes les valeurs ÷ nombre de valeurs. Elle est toujours entre la plus petite et la plus grande valeur.',
 c:C(`Tes notes du trimestre sont 12, 15, 9 et 14. Quelle note unique résume le mieux tes résultats ? C’est la <b>moyenne</b> : la note que tu aurais eue si toutes tes notes avaient été égales.`,
  [T('Calculer une moyenne',`<p><b>Moyenne = somme des valeurs ÷ nombre de valeurs</b>. Notes 12, 15, 9, 14 : (12 + 15 + 9 + 14) ÷ 4 = 50 ÷ 4 = 12,5.</p><p>On peut retrouver une valeur manquante : pour avoir 12 de moyenne sur 3 notes, il faut un total de 36.</p>`),
   T('Interpréter',`<p>La moyenne est toujours comprise entre la plus petite et la plus grande valeur. Elle est sensible aux valeurs extrêmes : 10, 11, 12, 47 → moyenne 20, alors que presque toutes les valeurs sont proches de 11.</p><p>Elle permet de comparer deux séries (deux classes, deux mois de températures…).</p>`)],
  [{q:'Températures d’une semaine : 12 ; 14 ; 11 ; 15 ; 13 ; 16 ; 10 (°C). Moyenne ?',s:['Somme : 12 + 14 + 11 + 15 + 13 + 16 + 10 = 91.','7 valeurs.','91 ÷ 7 = 13 °C.']}],
  ['J’additionne toutes les valeurs.','Je compte le nombre de valeurs.','Je divise la somme par ce nombre.','Je vérifie que le résultat est entre min et max.'],
  ['Oublier une valeur dans la somme ou dans le compte.','Diviser par un mauvais nombre.','Trouver une moyenne plus grande que la plus grande valeur.'],
  ['Moyenne = somme ÷ nombre de valeurs.','Min ≤ moyenne ≤ max.','La moyenne est sensible aux valeurs extrêmes.']),
 g:mix([d=>{const n=d===1?3:P([4,5,6]);const v=Array.from({length:n},()=>R(5,16));let s=v.reduce((a,b)=>a+b,0);if(s%n){v[0]+=n-s%n;s=v.reduce((a,b)=>a+b,0);}return num(`Notes : ${v.join(' ; ')}. Quelle est la moyenne ?`,s/n,{expl:`${v.join(' + ')} = ${s} ; ${s} ÷ ${n} = <b>${s/n}</b>.`,hint:'Somme ÷ nombre de notes.'});},3],
  [d=>{const n=P([3,4,5]),m=R(10,15),v=Array.from({length:n-1},()=>R(8,18));const last=m*n-v.reduce((a,b)=>a+b,0);if(last<0||last>20)return num(`Notes : ${v.join(' ; ')}. Somme des notes ?`,v.reduce((a,b)=>a+b,0),{expl:`Somme : <b>${v.reduce((a,b)=>a+b,0)}</b>.`,hint:'Additionne.'});return num(`Léo a eu ${v.join(', ')}. Quelle note doit-il obtenir au dernier contrôle pour avoir exactement ${m} de moyenne sur ${n} notes ?`,last,{expl:`Total nécessaire : ${m} × ${n} = ${m*n} ; il a déjà ${v.reduce((a,b)=>a+b,0)} ; il lui faut <b>${last}</b>.`,hint:'Moyenne × nombre de notes = total.'});},2],
  [d=>{const v=Array.from({length:6},()=>R(5,24));let s=v.reduce((a,b)=>a+b,0);if(s%6){v[0]+=6-s%6;s=v.reduce((a,b)=>a+b,0);}return num(`Températures (°C) : ${v.join(' ; ')}. Moyenne ?`,s/6,{unit:'°C',expl:`${s} ÷ 6 = <b>${s/6} °C</b>.`,hint:'Somme ÷ 6.'});},1],
  [bank([['Pourquoi la moyenne de 10, 11, 12 et 47 ne représente-t-elle pas bien la série ?','la valeur 47 tire la moyenne vers le haut',['elle est trop petite','il faut toujours 5 valeurs','la moyenne est toujours fausse'],'Une valeur extrême influence fortement la moyenne.'],{tf:'La moyenne d’une série peut être plus petite que sa plus petite valeur.',v:false,e:'Elle est toujours entre le minimum et le maximum.'}]),1])},

/* ======================= 5s ======================= */
{id:'5s',name:'Probabilités : hasard et équiprobabilité',icon:'🎲',domain:'Organisation et gestion de données',
 refs:[REF,PRG+' — 5e, « Probabilités » : vocabulaire (expérience aléatoire, issue, évènement), échelle de probabilité, probabilités en situation d’équiprobabilité, fréquences observées'],
 tip:'« Une chance sur quatre » se traduit par la probabilité 1/4 = 0,25 = 25 %.',
 c:C(`Lancer un dé, tirer une carte, jouer à pile ou face : ce sont des <b>expériences aléatoires</b> (on ne peut pas prévoir le résultat). On peut pourtant mesurer les chances de chaque résultat par une <b>probabilité</b>, un nombre entre 0 et 1.`,
  [T('Vocabulaire',`<p>Une <b>issue</b> est un résultat possible (lancer un dé : 1, 2, 3, 4, 5 ou 6). Un <b>évènement</b> est un ensemble d’issues (« obtenir un nombre pair » = {2 ; 4 ; 6}).</p><p>Échelle des probabilités : 0 = <b>impossible</b> ; 1 = <b>certain</b> ; 0,5 = autant de chances que de ne pas se produire.</p>`),
   T('Équiprobabilité',`<p>Quand toutes les issues ont la même chance (dé équilibré, pièce équilibrée…), <b>P = nombre d’issues favorables ÷ nombre d’issues possibles</b>.</p><p>Dé : P(obtenir 5) = 1/6 ; P(nombre pair) = 3/6 = 1/2. Une probabilité s’écrit en fraction, en décimal ou en pourcentage.</p><p>En répétant l’expérience un grand nombre de fois, les fréquences observées se rapprochent des probabilités.</p>`)],
  [{q:'Une urne contient 3 boules rouges et 5 bleues. P(rouge) ?',s:['8 boules, chacune a la même chance d’être tirée.','3 issues favorables.','P(rouge) = 3/8 = 0,375 = 37,5 %.']}],
  ['Je liste les issues possibles.','Je vérifie qu’elles sont équiprobables.','Je compte les issues favorables.','Je calcule la probabilité et je l’écris sous la forme demandée.'],
  ['Donner une probabilité supérieure à 1.','Oublier des issues dans le total.','Croire qu’un résultat « dû » devient plus probable après plusieurs échecs.'],
  ['0 ≤ P ≤ 1 : 0 impossible, 1 certain.','Équiprobabilité : favorables ÷ possibles.','« 1 chance sur 4 » = 1/4.']),
 g:mix([d=>{const e=P([['un 4',1],['un nombre pair',3],['un nombre impair',3],['un multiple de 3',2],['un nombre inférieur à 3',2],['un nombre supérieur à 6',0],['un nombre entre 1 et 6',6]]);return fracR(`On lance un dé équilibré à 6 faces. Probabilité d’obtenir ${e[0]} ?`,e[1],6,{expl:`${e[1]} issue${e[1]>1?'s':''} favorable${e[1]>1?'s':''} sur 6 : P = <b>${fr(e[1],6)}</b>${e[1]===0?' (évènement impossible)':e[1]===6?' (évènement certain)':''}.`,hint:'Compte les faces qui conviennent.'});},3],
  [d=>{const r=R(1,9),b=R(1,9);return fracR(`Une urne contient ${r} boule${r>1?'s':''} rouge${r>1?'s':''} et ${b} bleue${b>1?'s':''}. Probabilité de tirer une rouge ?`,r,r+b,{expl:`${r} rouge${r>1?'s':''} sur ${r+b} boules : P = <b>${fr(r,r+b)}</b>.`,hint:'Favorables ÷ total.'});},3],
  [d=>{const e=P([['Il neigera à Paris un jour de juillet (en général)','peu probable'],['Obtenir pile avec une pièce équilibrée','une chance sur deux'],['Obtenir 7 avec un dé à six faces','impossible'],['Le soleil se lèvera demain','certain'],['Obtenir un nombre inférieur à 6 avec un dé','très probable']]);return ch(`Place cet évènement sur l’échelle des probabilités : « ${e[0]} ».`,e[1],['impossible','peu probable','une chance sur deux','très probable','certain'].filter(x=>x!==e[1]),{expl:`Cet évènement est <b>${e[1]}</b>.`,hint:'Entre impossible (0) et certain (1).'});},2],
  [d=>{const k=P([2,4,5,10]);return ch(`« Une chance sur ${k} » correspond à la probabilité…`,`${fr(1,k)} = ${nf(1/k)}`,[`${k}`,`${nf(k/10)}`,`${fr(k-1,k)}`],{expl:`Une chance sur ${k} : P = 1/${k} = <b>${nf(1/k)}</b> = ${nf(100/k)} %.`,hint:'Une issue favorable sur k.'});},1])},

/* ======================= 5t ======================= */
{id:'5t',name:'Proportionnalité, pourcentages et coefficient',icon:'🔁',domain:'Proportionnalité, fonctions',
 refs:[REF,PRG+' — 5e, « Proportionnalité » : reconnaître une situation de proportionnalité (tableau, graphique), coefficient de proportionnalité, retour à l’unité, proportions et pourcentages'],
 tip:'Dans un tableau de proportionnalité, on passe d’une ligne à l’autre en multipliant toujours par le même nombre : le coefficient.',
 c:C(`Une recette pour 4 personnes demande 200 g de farine. Combien pour 6 personnes ? Pour 10 ? Quand les quantités sont <b>proportionnelles</b>, plusieurs méthodes permettent de calculer rapidement.`,
  [T('Reconnaître et calculer',`<p>Deux grandeurs sont proportionnelles si on passe de l’une à l’autre en multipliant par un même nombre, le <b>coefficient de proportionnalité</b> (prix unitaire, vitesse, échelle…).</p><p>Méthodes : <b>linéarité</b> (pour 8 personnes, deux fois plus que pour 4), <b>retour à l’unité</b> (pour 1 personne : 50 g, donc pour 6 : 300 g), coefficient.</p><p>Graphiquement, une situation de proportionnalité est représentée par des points <b>alignés avec l’origine</b>.</p>`),
   T('Pourcentages',`<p>Un pourcentage est une proportion sur 100 : 25 % = 25/100. Prendre 10 % de 80 : 80 × 0,10 = 8 ; 50 % c’est la moitié ; 1 %, c’est diviser par 100.</p><p>Pourcentage de voix : 12 voix sur 24 → 12/24 = 50 %.</p>`)],
  [{q:'4 kg de pommes coûtent 9,60 €. Prix de 3 kg ?',s:['Retour à l’unité : 9,60 ÷ 4 = 2,40 € le kilo.','3 × 2,40 = 7,20.','3 kg coûtent 7,20 €.']}],
  ['Je vérifie que la situation est proportionnelle.','Je choisis une méthode (linéarité, unité, coefficient).','Je calcule avec les unités.','Je vérifie la cohérence (plus de kg → plus cher).'],
  ['Ajouter au lieu de multiplier : si 2 kg ↔ 5 €, alors 4 kg ↔ 10 €, pas 7 €.','Croire que l’âge et la taille sont proportionnels.','Confondre 25 % et 1/25.'],
  ['Proportionnel : coefficient constant.','Retour à l’unité, linéarité, coefficient.','Graphique : points alignés avec l’origine.']),
 g:mix([d=>{const p=P([50,60,75,80,100,120,150]),q=P([2,4,5]),n=P([1,3,6,8,10].filter(x=>x!==q));return num(`Une recette pour ${q} personnes demande ${p*q/q*q} g de farine. Combien en faut-il pour ${n} personnes ?`,p*n,{unit:'g',expl:`Pour 1 personne : ${p*q} ÷ ${q} = ${p} g ; pour ${n} : ${p} × ${n} = <b>${p*n} g</b>.`,hint:'Retour à l’unité.'});},3],
  [d=>{const t=P([1,10,20,25,50,75]),n=P([40,60,80,120,200,300,500]);return num(`Calcule ${t} % de ${n}.`,n*t/100,{expl:`${n} × ${nf(t/100)} = <b>${nf(n*t/100)}</b>.`,hint:`${t} % = ${t}/100.`});},2],
  [d=>{const tot=P([20,24,30,40,50]),v=P([...Array(tot).keys()].filter(x=>x>0&&x*100%tot===0&&x<tot));return num(`Un candidat obtient ${v} voix sur ${tot}. Quel pourcentage des voix ?`,v*100/tot,{unit:'%',expl:`${v} ÷ ${tot} = ${nf(v/tot)} = <b>${nf(v*100/tot)} %</b>.`,hint:'Voix ÷ total × 100.'});},2],
  [d=>{const k=P([1.5,2,2.5,3,4]);const xs=[1,2,4,5];const ys=xs.map(x=>x*k);const prop=Math.random()<.5;if(!prop)ys[R(1,3)]+=1;return ch(`<table class="ptable"><tr><th>Quantité</th>${xs.map(x=>`<td>${x}</td>`).join('')}</tr><tr><th>Prix (€)</th>${ys.map(y=>`<td>${nf(y)}</td>`).join('')}</tr></table>Est-ce une situation de proportionnalité ?`,prop?'Oui':'Non',[prop?'Non':'Oui'],{expl:prop?`Prix = ${nf(k)} × quantité dans chaque colonne.`:'Le quotient prix ÷ quantité n’est pas le même partout.',hint:'Calcule prix ÷ quantité.'});},2],
  [d=>{const a=P([1,2,-1,0.5]);const b=P([0,0,2,-1]);return ch(`${graph([[a,b]])}Ce graphique représente-t-il une situation de proportionnalité ?`,b===0?'Oui : droite passant par l’origine':'Non : la droite ne passe pas par l’origine',[b===0?'Non : la droite ne passe pas par l’origine':'Oui : droite passant par l’origine','Oui : c’est une droite'],{expl:'La proportionnalité se reconnaît à des points alignés avec l’origine du repère.',hint:'Regarde le point (0 ; 0).'});},1])},

/* ======================= 5u ======================= */
{id:'5u',name:'Fonctions : « en fonction de »',icon:'📈',domain:'Proportionnalité, fonctions',
 refs:[REF,PRG+' — 5e, « Fonctions » : l’expression « en fonction de », tableaux de valeurs, placer des points, lire un graphique, formule simple de dépendance'],
 tip:'« Le prix en fonction du nombre de cahiers » : le nombre de cahiers est la grandeur qu’on choisit (en abscisse), le prix est celle qui en dépend (en ordonnée).',
 c:C(`La hauteur d’une plante dépend du nombre de jours ; le prix payé dépend du nombre de places achetées. On dit que la hauteur est <b>fonction</b> du temps, ou que le prix varie <b>en fonction</b> du nombre de places.`,
  [T('Tableau de valeurs et formule',`<p>Une formule traduit la dépendance : prix p = 8 × n pour n places à 8 €.</p><p>Tableau de valeurs : n = 1, 2, 3, 5 → p = 8, 16, 24, 40.</p><p>On place les points (n ; p) dans un repère : n en abscisse, p en ordonnée.</p>`),
   T('Lire un graphique',`<p>Un graphique cartésien montre comment une grandeur varie en fonction d’une autre. Pour lire la valeur correspondant à une abscisse, on part de l’axe horizontal, on rejoint la courbe, puis on lit l’ordonnée.</p><p>Si les points sont alignés avec l’origine, les grandeurs sont proportionnelles.</p>`)],
  [{q:'Un abonnement coûte 5 € plus 2 € par film. Exprimer le prix p en fonction du nombre de films f, puis calculer pour 4 films.',s:['p = 5 + 2 × f.','Pour f = 4 : p = 5 + 8.','p = 13 €.']}],
  ['Je repère quelle grandeur dépend de l’autre.','J’écris la formule ou je lis le tableau.','Je calcule les valeurs (ou je les lis sur le graphique).','Je place les points (x ; y) si on me le demande.'],
  ['Inverser les axes (grandeur qui dépend en abscisse).','Lire le graphique en partant de l’axe vertical pour une image.','Relier les points par des segments quand la situation ne le permet pas (valeurs entières seulement).'],
  ['« y en fonction de x » : y dépend de x.','Formule → tableau → graphique.','Points (x ; y) : x en abscisse, y en ordonnée.']),
 g:mix([d=>{const a=R(2,9),b=R(0,9),n=R(1,10);return num(`Le prix p (en €) en fonction du nombre n d’objets est p = ${a} × n${b?` + ${b}`:''}. Calcule p pour n = ${n}.`,a*n+b,{unit:'€',expl:`p = ${a} × ${n}${b?` + ${b}`:''} = <b>${a*n+b} €</b>.`,hint:'Remplace n.'});},3],
  [d=>{const a=R(-3,3)||2,b=R(-4,4);const xs=[0,1,2,3,4];const ys=xs.map(x=>a*x+b);const i=R(0,4);return num(`<table class="ptable"><tr><th>x</th>${xs.map(x=>`<td>${x}</td>`).join('')}</tr><tr><th>y</th>${ys.map(y=>`<td>${nf(y)}</td>`).join('')}</tr></table>Quelle valeur de y correspond à x = ${xs[i]} ?`,ys[i],{expl:`Dans la colonne x = ${xs[i]}, on lit y = <b>${nf(ys[i])}</b>.`,hint:'Lis la colonne.'});},2],
  [d=>{const a=P([1,2,0.5,-1]),b=R(-2,2);const xs=[-2,-1,0,1,2].filter(x=>Number.isInteger(a*x+b)&&Math.abs(a*x+b)<=5);const x=P(xs);return num(`${graph([[a,b]])}Lis sur le graphique la valeur de y pour x = ${nf(x)}.`,a*x+b,{expl:`On part de x = ${nf(x)}, on rejoint la droite, on lit y = <b>${nf(a*x+b)}</b>.`,hint:'Pars de l’axe horizontal.'});},2],
  [d=>{const f=P([['le périmètre P d’un carré en fonction de son côté c','P = 4 × c',['P = c + 4','P = c × c','P = 2 × c']],['l’aire A d’un carré en fonction de son côté c','A = c × c',['A = 4 × c','A = 2 × c','A = c + c']],['le prix p de n croissants à 1,20 €','p = 1,20 × n',['p = n + 1,20','p = n ÷ 1,20','p = 1,20']]]);return ch(`Quelle formule exprime ${f[0]} ?`,f[1],f[2],{expl:`${f[1]}.`,hint:'Traduis la situation.'});},2])},

/* ======================= 5v ======================= */
{id:'5v',name:'Algorithmique par blocs : séquences et boucles',icon:'🤖',domain:'La pensée informatique',
 refs:[REF,PRG+' — 5e, « La pensée informatique » : séquencer des instructions, entrées et sorties, formules dans un langage par blocs, prévoir une valeur, boucle « répéter n fois »'],
 tip:'Avant d’exécuter un programme, prévois le résultat à la main : écris la valeur de chaque variable après chaque instruction.',
 c:C(`Dans Scratch, on assemble des blocs : « demander », « mettre x à … », « répéter 4 fois », « avancer ». Comprendre l’<b>ordre des instructions</b> et ce que fait une <b>boucle</b> permet de prévoir ce que le programme va faire.`,
  [T('Séquence, entrée, sortie',`<p>Un programme exécute ses instructions <b>dans l’ordre</b>, de haut en bas. Une <b>entrée</b> est une donnée fournie au programme (« demander un nombre ») ; une <b>sortie</b> est un résultat affiché (« dire … »).</p><p>Une formule se traduit en blocs : « mettre résultat à (nombre × 3) + 2 ». Si l’on entre 5, le programme dit 17.</p>`),
   T('Boucle « répéter n fois »',`<p>« répéter 4 fois : avancer de 100 ; tourner de 90° » trace un carré. La boucle évite d’écrire 4 fois les mêmes instructions.</p><p>Avec une variable : « mettre x à 1 ; répéter 3 fois : mettre x à x × 2 » donne x = 8.</p>`)],
  [{q:'Programme : demander un nombre n ; mettre r à n × n − 1 ; dire r. Que dit-il si n = 6 ?',s:['Entrée : n = 6.','r = 6 × 6 − 1 = 35.','Sortie : le programme dit 35.']}],
  ['Je repère l’entrée (la donnée fournie).','J’exécute les instructions dans l’ordre.','Pour une boucle, je compte les répétitions.','Je lis la sortie.'],
  ['Changer l’ordre des instructions.','Faire une répétition de trop.','Confondre l’entrée et la sortie.'],
  ['Les instructions s’exécutent dans l’ordre.','Entrée : donnée ; sortie : résultat affiché.','« Répéter n fois » : n exécutions du bloc.']),
 g:mix([d=>{const a=R(2,9),b=R(1,15),n=R(1,12);const t=P(['a','b','c']);if(t==='a')return num(`Programme : demander n ; mettre r à n × ${a} + ${b} ; dire r. Que dit-il si n = ${n} ?`,n*a+b,{expl:`r = ${n} × ${a} + ${b} = <b>${n*a+b}</b>.`,hint:'Remplace n par la valeur entrée.'});if(t==='b')return num(`Programme : demander n ; mettre r à (n + ${b}) × ${a} ; dire r. Que dit-il si n = ${n} ?`,(n+b)*a,{expl:`r = (${n} + ${b}) × ${a} = <b>${(n+b)*a}</b>.`,hint:'Parenthèses d’abord.'});return num(`Programme : demander n ; mettre r à n × n − ${b} ; dire r. Que dit-il si n = ${n} ?`,n*n-b,{expl:`r = ${n} × ${n} − ${b} = <b>${n*n-b}</b>.`,hint:'Calcule n × n d’abord.'});},3],
  [d=>{const x0=R(1,9),n=R(2,5),k=R(2,6);const op=P(['+','×2']);let x=x0;for(let i=0;i<n;i++)x=op==='+'?x+k:x*2;return num(`mettre x à ${x0} ; répéter ${n} fois : ${op==='+'?`ajouter ${k} à x`:'mettre x à x × 2'}. Valeur finale de x ?`,x,{expl:`${n} répétitions à partir de ${x0} : <b>${x}</b>.`,hint:'Compte les répétitions.'});},3],
  [d=>{const n=P([3,4,5,6,8]);const nm={3:'un triangle équilatéral',4:'un carré',5:'un pentagone régulier',6:'un hexagone régulier',8:'un octogone régulier'}[n];return num(`« répéter ${n} fois : avancer de 80 ; tourner de … ° » trace ${nm}. De quel angle faut-il tourner ?`,360/n,{unit:'°',expl:`Le lutin fait un tour complet : 360 ÷ ${n} = <b>${360/n}°</b>.`,hint:'360° partagés en parts égales.'});},2],
  [bank([['Dans « demander un nombre », le nombre saisi est…','une entrée',['une sortie','une boucle','un lutin'],'C’est une donnée fournie au programme.'],['Combien de fois le bloc est-il exécuté dans « répéter 7 fois » ?','7',['6','8','1'],'Exactement 7 fois.']]),1])}
]);
})();
